/* 2016年9月27日 文教委員会 会議録全文（正式会議録／公式会議録の転載）。scripts/minutes_fulltext.py で生成。 */
window.SHINAGAWA_DB.registerMinutes({"id":"h28-20160927-9","dateIso":"2016-09-27","title":"2016年9月27日 文教委員会","sourceType":"formal","sourceUrl":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4894#one","fetchedAt":"2026-08-14","characters":64863,"voices":[{"i":1,"speaker":"あくつ委員長","text":"○午前１０時００分開会\nただいまより、文教委員会を開会いたします。\n本日は、お手元の審査・調査予定表のとおり、議案審査、請願・陳情審査、報告事項およびその他を予定しております。\n本日も効率的な委員会運営にご協力よろしくお願いいたします。\n本日は２名の傍聴申請がございますので、ご案内いたします。\n────────────────────────────────────────────\n１ 議案審査\n(1) 第８７号議案 品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する\n条例"},{"i":2,"speaker":"あくつ委員長","text":"初めに、(1)第８７号議案 品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例を議題に供します。\nそれではまず、本件につきまして理事者から説明願います。"},{"i":3,"speaker":"竹田保育課長","text":"第８７号議案 品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例についてご説明いたします。\n１．改正の理由ですが、建築基準法施行令が改正されたことに伴い、小規模保育事業Ａ型および事業所内保育事業の避難用設備に関する規定を改める必要が生じたため、品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正するものでございます。\n２．改正の内容ですが、小規模保育事業Ａ型等の保育室を建物の４階以上に整備する場合、避難用として屋内階段等を設置することとされており、保育室と階段室との間に、バルコニーまたは外気に向かって開くことができる窓や排煙設備を有する付室の設置が義務づけられていました。近年、排煙技術・工法が進んだことに伴い、より効果が発揮できるよう、1)階段室に排煙設備を設けること、または2)火災時に生じる煙が階段室に流入することを有効に防止できる付室を設けることとされたことから、必要な改正を行うものでございます。\n３．新旧対照表は別紙のとおりです。\n４．施行期日は公布の日から施行いたします。\n私からは以上でございます。"},{"i":4,"speaker":"あくつ委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":5,"speaker":"のだて委員","text":"今回、この改正で規制緩和による子どもたちの安全が脅かされるのではないかということを危惧しておりますけれども、３点お聞きしたいと思います。\n先ほど、今回の改正でより効果が発揮できるということでしたけれども、それは具体的にどういうことなのか、理由を教えてください。\nそして、現在、品川区内で４階以上にある認可、認証、小規模、そして、わかれば無認可の園の数も含めて、それぞれ教えてください。\nそして３点目、この改正で、保育園では避難路の確保ということで、子どもは基準が厳しいという声もありますけれども、この際、屋外階段などをなくしてもいいということになるのかどうか、確認したいと思います。"},{"i":6,"speaker":"竹田保育課長","text":"まず、今回の改正の理由でございますが、これは、規制緩和というよりも、排煙技術の進歩に伴い、有効な手段が増えたということに伴う、選択肢の幅が広がったというものでございます。\nそれから２番、現在の数でございますが、この条例での対象となる施設は、現在のところございません。その他については、済みません。ちょっと今、手元にございませんので、ご回答できません。\nそれから３番は、屋外階段を廃止ということですが、屋外階段も有効な避難方法の１つと考えておりますので、今のところはそういった考え方は示されていないところでございます。"},{"i":7,"speaker":"のだて委員","text":"そういう階段がなくなるということはないということでいいのかと受け取りましたが、もし違えばご答弁いただければと思います。\n１点目のところで、有効な手段が増えたと、今回のは規制緩和ではないということですけれども、今回の改正で、今まで設置できなかったところにも、避難用の階段が設置されて、４階以上のところにこの小規模の保育園ですとかが、増えていくようなことになると思うのですけれども、今回の技術の進歩というのは、どういったものがあるのか伺いたいと思います。"},{"i":8,"speaker":"竹田保育課長","text":"まず、屋外階段の考え方でございますが、国の議論の記録等を見ますと、やはり高層階にできた場合に、屋外階段を下が見えるような状況だと、本当に子どもたちがそこを使って避難できるのかというような問題がありますので、今後、屋外階段については検討していくというような議論がされておりますので、その議論を見守っていきたいと思っております。\nそれから、具体的にどういう技術がということなのですが、幾つか国のほうから示されておりまして、従来の外気に向かって開くことができる窓ということを含めて、それ以外に、やはり避難のときは階段に煙が行くことによって、避難ができなくなるということですので、加圧式で、付室と階段室の圧力を変えることによって、階段に煙が行かないような技術、あるいは排煙機による排煙設備、それから、最上部に、直接外気に開放する排煙設備を設けること等が示されているものでございます。"},{"i":9,"speaker":"のだて委員","text":"屋外階段については、下が見えることによって、本当に避難できるのかということでしたけれども、今後検討していくという、国のほうで検討されているということでしたけれども、やはりそういったことも、確かに下が見えて恐怖を感じることもあるとは思いますが、やはり子どもの安全がしっかり保たれていくことが重要だと思いますので、そういった視点で注視していっていただきたいと思います。\nあと、技術の進歩のところで、加圧式のものとか、階段室の上部に排煙設備を設けるというものができるようになったということですけれども、そういったものはやはり電気で動いていると思うのですけれども、停電時の場合、予備電源等というのはあるのでしょうか。"},{"i":10,"speaker":"竹田保育課長","text":"施設によって、構造等は異なると思いますが、非常時にも対応できるような設備にしていくように指導していきたいと思います。"},{"i":11,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":12,"speaker":"あべ委員","text":"現在、区内に４階以上の保育室はないということだったのですけれども、例えばこの条例の改正によって、４階以上にできやすくなるとか、そういう感触はありますか。あるいは、これがハードルになって、なかなか場所が見つからないというような状況というのはあるのでしょうか。"},{"i":13,"speaker":"大澤待機児童対策担当課長","text":"４階以上の園ということで、特に今、高層階の園について禁止されているわけではないのですけれども、事業者さんから提案があった場合、区としましては、新規開設の場合、できるだけ１階につくってほしいということでお願いしておりまして、１階でどうしてもできない場合でも、せめて２階ということでお願いしていますので、この条例の改正のあることによって、高層階にいきなりできやすくなるという、つくっていただくというような方向性を変える考えは今のところございません。"},{"i":14,"speaker":"あべ委員","text":"ありがとうございます。これまでも、区はできるだけ１階、あるいはぜいぜい２階ということで、そういう方向で持っていったと思いますし、今後もそれを現実としてやっていただきたいなと。４階というのはちょっと考えづらいものもありますので、そのとおりによろしくお願いいたします。"},{"i":15,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":16,"speaker":"飯沼委員","text":"この新しい、新しいというか、いろいろな選択肢ができて、今までのような安全性が階段室などで保たれていくという説明は、一定理解いたしました。今、やはり保育園不足というところで、なるべくさまざまな保育施設を屋内につくっていくというところで、品川区は１階とか２階になるべくという、その方向はとても大事であると思っていますけれども、既存の建物で２方向避難を確保したりするのがすごく困難だということで、既存のところだと多分工事をしたり、いろいろして使えるようにしていくのだと思うのですけれども、本条例が改正されたことに伴って、既存の改修が進んで、保育室が上の階でも、する、しないではなくて、可能性としてできていく、上に設けることが、確保がしやすくなっていくのかどうか、ちょっとそこが。さっきの質問と似ているのですが、危惧をしているところなのですが、いかがでしょう。品川区が認める、認めないよりも、そういう施設が上の階にできていく可能性が増えていくのかどうかというのを聞いています。"},{"i":17,"speaker":"竹田保育課長","text":"今回の、４階以上の規定ですが、従来からこの規定は、４階以上に関する規定はございまして、それを一部改正されたものですので、新たに４階以上が可能になったということではございません。４階以上と想定されるのは、駅の近くとか交通の便のいいところだと思いますが、そういったところは地価や家賃等も高いですので、なかなかそういうところで保育施設の経営が成り立っていくのかというのは、難しい課題もあろうかと思っております。"},{"i":18,"speaker":"飯沼委員","text":"ちょっと答えがずれているかなと思う。この条例が改正されることによって、保育室の確保が、既存の建物の改修によって、高層階に可能になると思うのですね。確保しやすくなる。可能にならないのですか。そこをちょっと、はっきりお答え下さい。"},{"i":19,"speaker":"竹田保育課長","text":"先ほども申し上げましたとおり、４階以上の規定は従来もございました。バルコニーまたは外に向かって開放できる窓という規定はございましたが、それだけではなく、非常時の選択肢が広がったということですので、可能性が増えたかというご質問ですけれども、安全性の選択肢は増えましたが、可能性といったものが大きく変わるものではないと思っております。"},{"i":20,"speaker":"飯沼委員","text":"変わらないですかね。改修等によって、選択肢が増えるということは、従来よりもよりやりやすくなる、確保しやすくなるという認識なのですけれども、違いますかね。"},{"i":21,"speaker":"竹田保育課長","text":"今回の改正の一番の趣旨は、やはり子どもの安全性を高めるということが趣旨でございますので、確保しやすくするための改正ではないと考えております。"},{"i":22,"speaker":"飯沼委員","text":"ちょっとこの点は疑問が残りました。\nあと、今回は、家庭的保育事業等の設備なのですけれども、認可保育園とか認証のところは、この部分はどこに含まれているのか。多分、建築基準法施行令の改定なので、みんな影響していると思うのですが、そこのところはどこであらわれているのか、教えてください。"},{"i":23,"speaker":"竹田保育課長","text":"民間保育園等につきましては、東京都の条例のほうで定めておりまして、そちらが改正されたというふうに聞いております。"},{"i":24,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。\nほかにご発言がないようですので、これで質疑を終了いたします。\n採決に先立ちまして、各会派の態度を確認いたします。\nそれでは、自民党・子ども未来からお願いいたします。"},{"i":25,"speaker":"鈴木（博）委員","text":"賛成します。"},{"i":26,"speaker":"あくつ委員長","text":"公明党。"},{"i":27,"speaker":"新妻委員","text":"賛成いたします。"},{"i":28,"speaker":"あくつ委員長","text":"共産党。"},{"i":29,"speaker":"飯沼委員","text":"意見を添えて、反対です。建築基準法施行令第１２３条の３項の改正のところは、建築課長にも保育課長にもお伺いして理解をしたところです。しかし、やはり改正に伴って、４階以上の階層に小規模事業所が、可能性は広がると思います。このことに関して、東京都の団体でも、認可保育園などもそうですが、保育関係者から、本当に１階とか２階が当たり前、この、既に４階ということが書いてありますけれども、階段室に煙が入らないとしても、４階以上の階層に乳幼児施設、好ましくないという心配の声がたくさん上がっています。私は慎重に考えていかなくてはいけない規制緩和の１つと捉えて、反対をいたします。"},{"i":30,"speaker":"あくつ委員長","text":"民進・無所属。"},{"i":31,"speaker":"あべ委員","text":"これは法改正に伴う条例改正ということですが、品川区では現実的に４階という選択肢は、今のところ方針としてとっていないということで、今後もその考え方でぜひ子どもたちの安全性をより確保する回答を、運営について指導しつつ、運用していただければと思います。条例そのものについては、これは法改正に伴う一時的なものと考えておりますので、賛成いたします。"},{"i":32,"speaker":"あくつ委員長","text":"高橋しんじ委員。"},{"i":33,"speaker":"高橋（し）委員","text":"賛成します。"},{"i":34,"speaker":"あくつ委員長","text":"それでは、これより第８７号議案 品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例について採決いたします。\n本案は、挙手により採決いたします。\n本案は原案のとおり決定することに賛成の方は挙手を願います。\n〔賛成者挙手〕"},{"i":35,"speaker":"あくつ委員長","text":"賛成多数でございます。\nよって、本案は、原案のとおり可決決定いたしました。\n────────────────────────────────────────────\n(2) 第９１号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条\n例の一部を改正する条例"},{"i":36,"speaker":"あくつ委員長","text":"次に、(2)第９１号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例を議題に供します。\nそれでは、本件につきまして理事者より説明願います。"},{"i":37,"speaker":"有馬学務課長","text":"それでは、第９１号議案についてご説明いたします。\n本案は、区立学校の学校医、学校歯科医、学校薬剤師の公務災害補償に関する条例の一部を改正するものです。学校医等は特別職の非常勤職員であり、別途条例で災害補償に関する事項を定めています。今回の改正は、公立学校の学校医、学校歯科医および学校薬剤師の公務災害補償の基準を定める政令が改正されたことに基づき、都条例においても条例が改正されたことを受けまして、区においても都条例に準じていることから、都と同様の条例改正案を提出するものでございます。\n内容は２点ございます。１つは、介護補償の限度額の改定。もう１つは、他の法律による給付との調整率の改定でございます。\nまず、(1)介護補償限度額の改定についてご説明いたします。この介護補償ですが、障害のために常時または随時介護を要する状態にあり、現に介護を受けている場合、その期間について、病院に入院している場合等を除き、補償額を支給するものです。その支給限度額ですが、例えば「ア」に示しているとおり、常時介護を要し実費を支出した場合について、１カ月当たりの限度額を１０万４,５７０円から１０万４,９５０円に、３８０円引き上げるものです。このほか、常時介護を要し、親族等による介護を受ける場合等、それぞれケースがここに示してありますけれども、いずれのケースも３８０円から１２０円の範囲で限度額の改定を行うものであります。\n次に、(2)他の法律による給付との調整率の改定です。付則第８条１項の表、傷病保障年金の項のうち、障害厚生年金にかかる部分の調整率、そして同条第３項の表の休業補償についての障害補償年金等にかかる調整率を、それぞれ０.８６から０.８８に引き上げるということで、改めるものでございます。\n添付の資料といたしまして、新旧対照表をつけておりますけれども、３ページのほうには、付則の第８条の表で、一番上段のところ。それから、５ページの部分については、第３項の表で、やはり一番上段ということで、率が改定をしております。これは、他の公的年金と条例による災害補償給付が同一の公務災害を理由として両方から支給される場合に、災害補償の支給について一定割合を減ずる調整の仕組みを定めており、今回、その率を改正するものです。\n施行期日は条例公布の日とするものでございます。\nなお、都条例同様、経過措置を規定し、平成２８年４月１日を適用日といたします。\n私からの説明は以上です。"},{"i":38,"speaker":"あくつ委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":39,"speaker":"のだて委員","text":"２点目の、調整のところなのですけれども。こういった、ダブルで受けている方というのが、区内ではいるのかどうか伺いたいと思います。\nあと、今回の改正に至った経緯も教えてください。"},{"i":40,"speaker":"有馬学務課長","text":"まず、このダブルで受けている人が区内にいるかということでございますけれども、まずこの学校医の公務災害補償の制度ですけれども、平成１４年までは都条例によって規定されておりました。その後、条例が改正されまして、平成１４年から市区町村が自ら行うということで条例を制定いたしましたけれども、そもそも、この公務災害を受けた学校医等がおりませんので、そういう意味では、実例が今までないと。公務災害を受けた人はいないということでございます。\nそれから、今回、この条例の趣旨でございますけれども、まず基本的には、冒頭にも申し上げましたけれども、国のほうでまずこの学校医の災害補償に、学校医というか国家公務員の、人事院が定める公務災害補償における介護補償の引き上げが、まず行われたということがもとになっております。これを受けまして、東京都のほうでも、それぞれの改正が行われまして、その公務災害補償における学校医の部分の改正を受けて、区は、東京都のほうに準じておりますので、それに合わせる形で今回の条例改正をするという形になったものでございます。"},{"i":41,"speaker":"のだて委員","text":"済みません。ちょっと勉強不足で申しわけないのですけれども、この人事院の勧告が変更になったその経緯も、ぜひ教えていただければと思います。"},{"i":42,"speaker":"有馬学務課長","text":"まず、基本的に、我々公務員の給与は、毎年、人事院の勧告に基づいて見直しをされるということになっております。学校医の報酬につきましても、例えばこれは、公立学校ですと、東京都の人事委員会勧告に基づいておりますので、都の基準をベースに改定は行われるというものが基礎になっております。そういうことを受けまして、今回の改正になったということでございます。"},{"i":43,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":44,"speaker":"あべ委員","text":"ちょっと素朴な疑問で恐縮なのですけれども。これ、十数年間、条例をつくってから全く実例はないということで、でも、この金額の改正の条例というのは、わりと何度も行われていたかなと思うのですね。これ、条例に金額が入ってしまうと、金額が変わるたびに条例改正の手続きを毎回毎回しなければいけなくて。条例によっては、こうした金額は外に出してしまって、別に定める、という形でやっていることによって、金額が変わるたびに条例改正しなくてもいいみたいなのも、たくさんあるわけですね。この条例って、今さらそうはできないのかもしれないのですけれども。何かこう、これからもほとんど使う方がないだろうなと思われる内容。国から、都からといって、改正していくことになるのでしょうか。"},{"i":45,"speaker":"有馬学務課長","text":"委員のご指摘のとおり、毎年のように、まず、基本的には、今回は介護補償という部分でしたけれども、毎年ほとんど行われるのが、補償基礎額のところ。これはまさに給与改定に連動している部分ですので、毎年あるような形になっています。それで、実例もないということで、今、私のほうでも、教育委員会のほうとしても、今、委員が言われたような方式、いわゆる、改定は都の条例に準拠するみたいな形にしておけば、毎回改正しなくても済むのではないかということで、ちょっと各区のほうも調べておりまして、何区かがそういうやり方をしているということがわかりましたので、ちょっとこれから研究をさせていただきたいというふうに思っております。"},{"i":46,"speaker":"あべ委員","text":"可能な限りそのような方向で、できるだけ形式的なものはしないで済むように。"},{"i":47,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。\nほかにご発言がないようですので、これで質疑を終了いたします。\n採決に先立ちまして、各会派の態度を確認いたします。\nそれでは、自民党・子ども未来からお願いいたします。"},{"i":48,"speaker":"鈴木（博）委員","text":"賛成します。"},{"i":49,"speaker":"あくつ委員長","text":"公明党。"},{"i":50,"speaker":"新妻委員","text":"賛成します。"},{"i":51,"speaker":"あくつ委員長","text":"共産党。"},{"i":52,"speaker":"のだて委員","text":"賛成です。"},{"i":53,"speaker":"あくつ委員長","text":"民進・無所属。"},{"i":54,"speaker":"あべ委員","text":"賛成します。"},{"i":55,"speaker":"あくつ委員長","text":"高橋しんじ委員。"},{"i":56,"speaker":"高橋（し）委員","text":"賛成します。"},{"i":57,"speaker":"あくつ委員長","text":"それでは、これより第９１号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例について採決いたします。\nお諮りいたします。\n本案は原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":58,"speaker":"あくつ委員長","text":"ご異議なしと認めます。\nよって、本案は、全会一致で原案のとおり可決決定いたしました。\n────────────────────────────────────────────\n(3) 第８５号議案 平成２８年度品川区一般会計補正予算（歳出 文教委員会所管分）"},{"i":59,"speaker":"あくつ委員長","text":"次に、(3)第８５号議案 平成２８年度品川区一般会計補正予算（歳出 文教委員会所管分）を議題に供します。\nそれでは、本件につきまして理事者より説明願います。"},{"i":60,"speaker":"高山子ども育成課長","text":"それでは、私のほうから第８５号議案 平成２８年度品川区一般会計補正予算、歳出、子ども未来部の所管する部分についてのご説明を申し上げます。\n補正予算書の１４ページをお開きください。１４ページ、３款民生費、２項児童福祉費、１目児童福祉総務費につきましては８,０００万円を追加し、４８億７,１０３万１,０００円とするものでございます。\n右側、１５ページの説明欄をお開きください。保育事業助成追加分として、認証保育所運営費等助成の運営費助成として８,０００万円を計上してございます。\n続きまして、左側１４ページにお戻りいただきまして、その下、２目児童措置費につきましては、６３０万円を追加し、１４２億８４２万４,０００円としているものでございます。\n右側、１５ページの説明欄をごらんください。児童保育委託追加分としまして、学校１１０番設置費助成に、新たに小規模保育事業を追加した増額分として６３０万円を計上してございます。\n私からの説明は以上でございます。\n引き続きまして、保育課長より詳細の説明をさせていただきます。"},{"i":61,"speaker":"竹田保育課長","text":"保育課所管分についての内容をご説明いたします。\n１目児童福祉総務費、補正額８,０００万円分についてですが、お手元の資料、認証保育所運営費の単価改正についてをごらんください。認証保育所は待機児童対策を機動的に進めるために、東京都が認証する、主に乳幼児を対象とする認可外施設です。認証保育所の運営費につきましては、法定価格に基づく施設型給付費の支給は受けておりません。この度、平成２８年度運営費の法定価格が改正されたことを受け、認可保育園と認証保育所との均衡を図るため、東京都は補助単価を改正し、単価増を行うことから、補助金交付事務を担う区においても補助単価を改正するとともに、平成２８年４月にさかのぼって、２４カ所の認証保育所に交付するため、補正予算を計上するものでございます。\n運営費助成の改正内容ですが、(1)運営費基本分として、各保育所全体の園児数による規模別、年齢別に定められた単価の増額を行います。具体例を申し上げますと、園児数が４０人までの規模の園では、０歳児１人当たりの単価が、改正前は月額１５万３,４５０円でしたが、改正後は１５万５,７７０円となり、その差２,３２０円、単価アップするものでございます。この運営費基本分増額分が、２４施設の合計で１,７００万円でございます。\n(2)番、園が支払う賃借料に対して助成する賃借料加算でございます。賃借料の実勢価格に応じて充実を図るものでありまして、賃借料加算増額分として６,３００万円でございます。\n合わせて８,０００万円の補正を行うものでございます。\nまた、２目児童措置費、補正額６３０万円についてですが、お手元の資料、小規模保育事業に対する学校１１０番設置費助成の実施についてをごらんください。緊急時の通報装置である学校１１０番の設置費の助成は、これまで保育施設のうち、認可保育園、認証保育所を対象としてきましたが、対象施設を拡大し、新たに小規模保育事業も対象施設とし、区内２１事業所に対して新たに設置費の助成を行うため、補正予算を計上するものでございます。学校１１０番の仕組みは、お手元の資料の４のとおりでございます。\n私からの説明は以上でございます。"},{"i":62,"speaker":"あくつ委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":63,"speaker":"のだて委員","text":"まず、認証保育所の運営費の単価改正のところでお聞きしたいのですけれども。今回、運営費の基本分と賃借料加算というのが増額になるということなのですけれども、この補助単価の全体像がどうなっているのかをお聞きしたいのですが、この２つのほかに、加算とか減額というのはあるのか、伺いたいと思います。\nあと、２点目の賃借料加算のほうなのですが、事務事業概要の冊子を見ると、開設支援で行っている家賃支援補助というのも、開設後の家賃補助ということであるのですけれども、今回のこの賃借料加算との関係性をご説明いただきたいと思います。\nそして、今回出されたこの単価なのですが、園児１人当たり、１カ月の単価ということでいいのか、確認です。"},{"i":64,"speaker":"竹田保育課長","text":"まず、今回の単価の仕組み、運営費の仕組みというお話でしたけれども、各施設の月初に在園する園児数、年齢別の園児数に単価を掛けまして、運営費を算出して支出するものでございます。これ以外にも、障害児を受け入れた場合、アレルギー対応をした場合等々、加算項目がございまして、その加算項目に従って支給しているところでございます。\nそれから、今回の家賃補助については、実勢価格と加算額に開きがあったということで、実勢に近づけるために充実したものですが、こちら、基本的には月々の運営費を対象としたものでございます。こちらは、先ほど申し上げたとおり、児童１人当たりの単価でございます。"},{"i":65,"speaker":"のだて委員","text":"賃借料加算との関係性は。"},{"i":66,"speaker":"竹田保育課長","text":"今回の賃借料は、月々の運営費に対する部分ですので、開設支援のほうはまた別途規定しております。"},{"i":67,"speaker":"のだて委員","text":"別の点。今回のものは、月々の運営費だということだったのですが、事務事業概要の説明では、開設支援の家賃支援補助、これも開設後の家賃補助という説明が書いてあったのですが、これはそうすると同じことというか、開設後月々の運営費の補助ということになってくるのかと思うのですが、その関係性を教えていただければと思います。"},{"i":68,"speaker":"大澤待機児童対策担当課長","text":"開設後の家賃補助につきましては、坪単価で１万２,０００円を超える場合に、超えた部分を上限１万円までで５年間、区として補助する運用でございますので、今回の賃借料加算とはまた別枠として補助しているものでございます。"},{"i":69,"speaker":"あくつ委員長","text":"よろしいですか。"},{"i":70,"speaker":"のだて委員","text":"学校１１０番のほうをお聞きしたいのですが、今回、新たに小規模のほうにも設置していくというところで、どういったシステムになっているのか、そしてどういう工事が必要になってくるのか、どんな事業者が工事していくのかということもご説明いただければと思います。\n今回、設置した後に、ランニングコストというのはかかってくるのか伺いたいと思います。"},{"i":71,"speaker":"竹田保育課長","text":"学校１１０番の仕組みでございますが、受話器とボタン部分が独立してございまして、それでボタンを押すことによって緊急通報が警視庁の司令部のほうに届きます。それと、それに基づいて最寄りの警察等が緊急で駆けつけるわけなのですが、ボタンを押すだけでなく会話が必要な場合に、その受話器をとって会話もすることができるという内容でございます。\nそれから、どういった工事ということですが、各施設によって異なりますが、設置場所は保育園の中ですと、多くは事務所の緊急時に使うことを想定した使いやすい場所に設置しているところでございます。\nそれから、ランニングコストについては、済みません。ちょっと今、手元に資料がございません。"},{"i":72,"speaker":"のだて委員","text":"どういう工事が必要かということもお聞きしたので、誰が工事していくのか、どういう事業者になるのか、伺いたいと思います。\n今回、ボタンを押すことですぐさま緊急通常ができるということで、電話するよりも早いということで、効果があるということで設置していくということだと思うのですけれども、そういうことでいいのか確認です。"},{"i":73,"speaker":"竹田保育課長","text":"こちらを運営を行っている団体がございまして、ＮＰＯ法人東京都セキュリティ促進協力会というところが、そこに加入している法人、企業等が多数ございまして、こちらのほうでこのシステムを運営しておりますので、こちらの参加企業等が実際に工事等を行うものでございます。\nそれから、こちらのメリットでございますが、もうボタンを押すだけで通報ができるということで、緊急性を重視したという点が、こちらの最大のメリットでございます。"},{"i":74,"speaker":"のだて委員","text":"工事はどういうものが必要なのかというところで、大規模な工事が必要になってくるのでしょうか。新たに配線を変えたりとか、そういったことも必要になってくると、小規模保育事業の運営のほうにも影響が出てくると思うのですが、どういった工事が必要なのか、改めて伺いたいと思います。"},{"i":75,"speaker":"竹田保育課長","text":"もの自体は、受話器とボタン部分だけですので、スペース的には本当に限られた、壁面に設置するような小さなスペースですので。あとは配線、あるいは電源等でございますので、そんな大規模な改修工事というのは必要ないと考えております。"},{"i":76,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":77,"speaker":"新妻委員","text":"ありがとうございました。今回は追加ということで、補正に組まれているのですが、今後これから区内の中に小規模保育所が新たにできる場合というのは、最初からそれが設置をされるということでよろしいのでしょうか。"},{"i":78,"speaker":"大澤待機児童対策担当課長","text":"新たに開設する場合は、学校１１０番も順次、新規で取りつけるようにしてしていく予定でございます。"},{"i":79,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":80,"speaker":"あべ委員","text":"ちょっと確認なのですが。先ほどご答弁のあったＮＰＯ、東京都セキュリティ、何とおっしゃいましたっけ。"},{"i":81,"speaker":"竹田保育課長","text":"ＮＰＯ法人東京都セキュリティ促進協力会でございます。"},{"i":82,"speaker":"あべ委員","text":"ありがとうございます。この事業は、東京都の１０分の１０の補助事業ということですので、単価が３０万円というのは高いか安いかというのは、直接は区にはかかわらないところではあると思うのですけれども。\nこれを入れること自体には賛成です。やはり非常ボタンがあったほうがいいというのはわかりますけれども。\nこのセキュリティ促進協力会というのは、区としては、ここにもう全てをお願いする形なのでしょうかね。例えば、機種とか事業者とかは、一切かかわらず、あちらが決めて、あちらの仕組みで、あちらが決めて工事するという形になるのでしょうかね。"},{"i":83,"speaker":"竹田保育課長","text":"こちらの団体は、東京都が契約している団体ですので、実際の工事のほうは、こういったノウハウをお持ちのところがやったほうが一番効率的なのかと思いますが、ちょっとほかの事業者、区内の事業者等ができるかどうかについては、ちょっと研究したいと思います。"},{"i":84,"speaker":"あべ委員","text":"これ以上言っても何なのですが。このＮＰＯさん、例えば、都や警視庁のＯＢが大勢いらっしゃるとか、そういう性格のものではないですよね。これは、こちらで調べてみます。以上です。質問するにも、また。済みません。こちらで調べます。"},{"i":85,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":86,"speaker":"飯沼委員","text":"まず、認証保育所の運営費の単価改正なのですけれども、認証の補助金の制度がよくわからないのですが。さっき、加算の補助もあるということなのですが、おおよそは、区の運営費の基本分が、運営をしていく大もとであるという解釈でよろしいのか。今回は１,７００万円の追加ということなのですが、全体的にはこれで幾らぐらいの補助になるのか、教えていただきたいのが１点です。\nあと、一般財源ということになっていますけれども、これは財調ですよね。これがいつぐらいにお金が入ってくるのかも教えてください。"},{"i":87,"speaker":"竹田保育課長","text":"認証保育所の運営費は、基本的にはこちらの基本部分が主なものでございます。それ以外にも、冷暖房加算とか、賃借料加算とか、各種の加算項目を加えてそれぞれの施設に支給してまいるものでございます。予算規模としましては、１年間で約１３億円ほどを予定しているところでございます。"},{"i":88,"speaker":"飯沼委員","text":"予算規模が１３億円ということなのですけれども、ここに関しては、品川区独自の補助というものがあるのかどうかお聞かせいただきたいのが１点です。\nあと、賃借料の加算のところなのですが、ちょっと賃借料の加算という名目で出ていたことを、今まで知らなかったので、区の概要を見たら、全然そういう部分が載っていないのですね。開設準備と、坪単価が高いところへの家賃補助というのが書いてあるだけで、基本的なところが抜けていたので、今日お伺いして、知りたいと思ったことなのですけれども。賃借料の加算も、今回６,３００万円、かなり大きいのですが、この辺の全体の規模、予算の規模も教えてください。"},{"i":89,"speaker":"竹田保育課長","text":"賃借料に関する規模でございますが、約３,４００万円ほどを予定しているものでございます。\nそれから、品川区の独自補助という点では、認証は、大きなものは特段ございません。"},{"i":90,"speaker":"飯沼委員","text":"今ちょっと、賃借料のところ、規模は３,４００万円で、今回加算の額のほうが大きいということですか。今までの賃借料加算よりも、今回、増額分、かなり、では、賃借料のところの増額が大きくなったという捉え方でいいのでしょうか。"},{"i":91,"speaker":"竹田保育課長","text":"こちら、お手元の資料をごらんのとおり、倍以上の増額になっておりますので、当初予算に比べて大きく増額になる予定でございます。"},{"i":92,"speaker":"飯沼委員","text":"事業者さんとしては、大変、家賃とか高いので助かる中身であると思うのですが、この辺、この加算がされる経緯とかは、何か都のほうから聞いているのかどうか、その辺を教えてください。"},{"i":93,"speaker":"竹田保育課長","text":"賃借料の実勢価格と、今までの加算額が開きがあったということで、その地価相場、実勢価格に近づけるといいますか、即した内容に充実するための改正だというふうに聞いております。"},{"i":94,"speaker":"飯沼委員","text":"先ほど、区の加算はほとんどないということなのですが、その辺って、かなり、東京都の制度ではありますけれども、区内の待機児を受け入れているというところでは、大事な役割を果たしていると思うのですが、その辺の、認証保育園の運営費とか補助については、家賃補助があるのですけれども、考えていないところはなぜなのかなと、少し、ご配慮が必要ではないかなと思っているのですが、いかがでしょうか。"},{"i":95,"speaker":"竹田保育課長","text":"認可保育園と認証保育所は、基本的に性格が異なるものだと考えております。今後、認証保育所の支援については、検討していきたいと考えております。"},{"i":96,"speaker":"飯沼委員","text":"検討してくださるのですか。何かすごくありがたいご答弁だと思うので、期待をするのですが、ぜひ、前向きにご検討をお願いしたいと思います。かなり運営が大変と思いますので。\nあと、小規模保育事業の１１０番のほうなのですけれども、これって、ランニングコスト、さっきわからないと言っていましたよね。ほとんどかからないのですかね。\nあと、先ほど、工事の設置のところが、ＮＰＯで東京都のところで一括ということだったのですけれども、話を聞いたら、簡単な工事で終わるといった中身においては、ぜひ地元の電気工事ですか。どこになるかあれですけれども、地元に発注をするような申請、こういう工事は地元の発注をしていただけるような仕組みにしていただきたいなと思うのですが、いかがでしょうか。"},{"i":97,"speaker":"竹田保育課長","text":"ランニングコストでございますが、実際にこちらの設備を利用する場合というのは、今のところ、幸いなことにほとんどないと聞いておりますので、訓練等のときの使用のみとなっておりますので、基本的にランニングコストはそんなにかからないものだと思います。\nそれから、実際の設置に当たっての方法等については、研究してまいりたいと思っております。"},{"i":98,"speaker":"飯沼委員","text":"今、ちらっとお答えいただいた、実際に余り、ケース的には使われていないということでよろしいのでしょうか。"},{"i":99,"speaker":"竹田保育課長","text":"実際に、緊急時、緊急な事件が発生して、そのボタンを押して応援を求めたというのは、近年はないというふうに聞いています。"},{"i":100,"speaker":"飯沼委員","text":"このような設備は使われないほうがいいのであって。学校から始まったと思うのですけれども、学校のほうでも、そういった事例は余りないというか、安心させていただきたいところなのですが、いかがでしょうか。"},{"i":101,"speaker":"村尾教育総合支援センター長","text":"この１１０番の通報システムは、まさに、多分平成１３年の大阪の池田小事件があってからつけられたものということで、学校のほうでも避難訓練または防災訓練等で、不審者対応では使っていますが、学校に不審者が入ってボタンを押したというのは、私の記憶では多分ないかなというふうに思っています。"},{"i":102,"speaker":"飯沼委員","text":"ありがとうございます。"},{"i":103,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":104,"speaker":"沢田副委員長","text":"今ちょっと、学校１１０番のことなのですけれども。安全に対しては、幾ら金をかけてもかけ過ぎることはないという部分もあるかと思うのですけれども、この安全とか防犯とかに関して、文教委員会の中でのことだけでもないですけれども、例えば、障害者施設も高齢者施設もそうですし、また学校でもこういった学校１１０番という制度がありますし、また、品川区は近隣セキュリティシステムというすばらしいシステムを持っていますけれども、この辺のもう少し整理というか、効率的な運用というのは何かできないのか。これは都の事業なので、学校１１０番ということで、学校とか、今回、私立幼稚園とか私立保育園とか認証保育所ということになっていますけれども、いろいろな、安全に対する通報システムが区内にもたくさんあると思うのですが、この辺の、もう少し一本化というか、整理というのはできないのかなと思うのですけれども。ちょっと、この保育園だけではないのですけれども、その辺のお考えがあればと思うのですけれども。"},{"i":105,"speaker":"中島教育長","text":"この、保育所、保育園等も含めました、学校、子どもたちのそういった居場所の安全対策というのは、さまざまな方策がされておりますけれども、今、副委員長がおっしゃったような、なかなか一本化という体制での設置にはなっていないものですから、今からそれらの設備を一本化するというのは、なかなか難しいことかと思います。さまざまなこういうセーフティーネットを重ねて置くことによって、漏れを少なくしていくというのが、基本的な考え方だろうと思いますので、システムそれぞれの特徴を知りながら、どこかでも、どこかで防波堤になれるような形を考えていきたいなと思います。"},{"i":106,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。\nほかにご発言がないようですので、これで質疑を終了いたします。\n採決に先立ちまして、各会派の態度を確認いたします。\nそれでは、自民党・子ども未来からお願いいたします。"},{"i":107,"speaker":"鈴木（博）委員","text":"賛成します。"},{"i":108,"speaker":"あくつ委員長","text":"公明党。"},{"i":109,"speaker":"新妻委員","text":"賛成します。"},{"i":110,"speaker":"あくつ委員長","text":"共産党。"},{"i":111,"speaker":"のだて委員","text":"賛成。"},{"i":112,"speaker":"あくつ委員長","text":"民進・無所属。"},{"i":113,"speaker":"あべ委員","text":"賛成します。"},{"i":114,"speaker":"あくつ委員長","text":"高橋しんじ委員。"},{"i":115,"speaker":"高橋（し）委員","text":"賛成します。"},{"i":116,"speaker":"あくつ委員長","text":"それでは、これより第８５号議案 平成２８年度品川区一般会計補正予算（歳出 文教委員会所管分）について採決いたします。\nお諮りいたします。\n本案は原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":117,"speaker":"あくつ委員長","text":"ご異議なしと認めます。\nよって、本案は、全会一致で原案のとおり可決決定いたしました。\n以上で議案審査を終了いたします。\n────────────────────────────────────────────\n２ 請願・陳情審査\n(1) 平成２８年請願第１１号 ひろまち保育園の公設公営を求める請願\n(2) 平成２８年請願第１３号 ひろまち保育園を区直営の保育園にすることを求める請願"},{"i":118,"speaker":"あくつ委員長","text":"次に予定表２、請願・陳情審査を行います。\n平成２８年請願第１１号 ひろまち保育園の公設公営を求める請願、および平成２８年請願第１３号 ひろまち保育園を区直営の保育園にすることを求める請願を議題に供します。\n本件は初めて取り上げますので、書記に朗読させます。\n〔書記朗読〕"},{"i":119,"speaker":"あくつ委員長","text":"朗読が終わりました。\n本件につきましては関連する内容の請願であるため、一括して質疑を行った後、個別に採決を執り行うことといたします。\nそれでは、本件につきまして、理事者の説明を求めます。"},{"i":120,"speaker":"竹田保育課長","text":"平成２８年請願第１１号 ひろまち保育園の公設公営を求める請願、および平成２８年請願第１３号 ひろまち保育園を区直営の保育園にすることを求める請願についてご説明いたします。\n昨年度、品川区では２３区で２番目に多い７９８人の子どもの数が増えております。区の確かな区政運営と魅力が的確に発信されている成果と受け止めておりますが、子ども・子育て計画で想定した以上に、子どもの人口が増加していることなど、待機児童対策は区にとって重要な施策の１つと考えております。\n平成２２年から平成２７年までの６年間で、区は３,６２４人の保育定員を拡大し、平成２８年度には８３９人の受け皿の拡大を実施いたしました。ひろまち保育園は、平成２８年に開設した認可保育園です。再開発地を、５年間という期間を限定して開設し、定員３００人という大規模保育園として、待機児童対策という喫緊の課題に応えるという考えのもと、開設しております。運営に当たっては、業務委託という手法によっています。これは、５年間という期限が定まった中で、５０人近い保育士等の確保は区では困難であったことがございます。幸い、区立保育園で保育士として勤務した経験のある方が受託事業者の職員として採用されましたので、これら十数人が中核となって保育が実施されており、開園以来、半年が経過しましたが、保護者からの、園長以下、保育士への評価も高く、合意解除が報道された後も支障なく運営が図られております。\nひろまち保育園の委託業者の選定については、公募を行い、５社から応募をいただきました。区は、書類審査、ヒアリングによる２次審査を行い、現在の事業者を最上位として、受託事業者としたものですが、審査に当たっては「のびのび育つ しながわっこ」に基づき、区の保育に対する考え、方針を系列的に明示しており、契約に当たっても、覚書、仕様書をもとに十分説明し、承諾させています。\n先ほどご説明したとおり、業務委託による保育の実施であり、定期的な話し合いを、法人の理事長、または理事長の配偶者である統括園長と実施してまいりましたが、本年５月ごろより、ひろまち保育園を全国展開する法人の他の保育園と同様に考え、その１つに過ぎないと態度を変え、双方の認識にずれが生じました。\n６月には、兵庫県姫路市で運営している私立認可保育園について、その運営補助金が不正に流用されているとの報道がございました。区としても、その事実の確認と、区がひろまち保育園開設に当たって不適切な支出がないかを確認するため、開設準備経費４,９５５万円分の全件の領収書・レシートの点検のための開示を求め、区として厳しく点検いたしました。区としては、相手方法人の姫路市の件で事実の説明が十分ではなかったと認識しております。一方で、相手方法人は、不適切な支出はないと説明しているにもかかわらず、区が繰り返し保育の状況のチェックを行っているという認識があり、双方に溝が生じました。\n区としましては、保育の実施を委託することは、経常的な信頼関係が不可欠であることから、区が保育状況について、業務委託という契約の方針に従い、直接園長に指示したいと申し出を行いましたが、相手方法人としては、法人としての保育方針に基づき園運営を行うという立場を堅持し、双方に妥協が厳しいことが確認されました。区が年度いっぱいで委託業務契約の解除に合意するか否かを照会したことに対し、相手方法人は７月の理事会で合意解除を議決しました。その後、双方で弁護士を入れて協議し、合意解除に向けた整理を行い、８月１９日、合意解除の運びとなりました。\n保護者の皆様への対応でございますが、８月２３日に説明会を行いました。約１１０名の方が参加され、本日、やりとりを整理したものを資料としてお配りしました。報道によって、合意解除により保育士が変わってしまうと理解されておりました。保育内容には満足しているけれども、子どもたちのために保育士は変わらないでほしいとのご意見が多くございました。当日、保護者会では、冷静に区の説明を聞いていただき、おおむね４５分の質疑を行っております。現時点では、保育士は相手方法人の職員であり、区として雇用継続について明確なお話をできる立場ではございませんが、円滑な保育の引き継ぎができるよう、新しい事業者と十分話し合いの場を持ってまいります。\n請願項目ですが、請願第１１号の請願項目１と、請願第１３号の請願項目１は共通しておりまして、区直営の認可保育園に移行してほしいとの件ですが、保育の実施については、現在のひろまち保育園に特段の問題はございませんので、新しい事業者にも円滑に引き継げるよう、区としても万全を尽くしてまいります。\nまた、保育士の採用試験も終了しており、人事計画上、他の園から区の保育士を異動または配置し、通常の運営は困難と考えております。直営での運営は困難と考えております。\n次に、請願第１１号、請願項目２の、半年で契約を撤回と発表した原因を明らかにとの件ですが、先ほどご説明したとおり、保育の方針に隔たりがあったこと、運営補助金の不正流用でも十分な説明がされず、信頼関係の継続が困難と考えたことに至るものでございます。\n以上でございます。"},{"i":121,"speaker":"あくつ委員長","text":"説明が終わりました。\nこれより質疑を行います。ご発言願います。"},{"i":122,"speaker":"のだて委員","text":"まずちょっと確認したいのですが、今、ご説明の中に、区のほうで直接園長に指示したいと言ったけれども受け入れられなかったというお話がありましたが、これは報道でも、理事長の関与をさせないよう区が求めたという報道もありましたけれども、こういったことがそういうふうに受け取られたということなのか、１点、そこは確認です。\n示されました保護者会の資料について、ちょっとお聞きしたいのですが。この中で、２番のところで、建設中止の動きが、ということが書かれておりますけれども、この、他自治体で同事業者のところでそういった動きがあるということですが、これがどこかということは、区はつかんでいるのか、どこかわかっていれば教えていただきたいと思います。\n２点目が、その２番で、保護者に心配をかけないように契約を１年で終了したとありますけれども、この、区の考える心配とは何か、伺いたいと思います。\n何番かすぐ見つかりませんが、できるだけ今の保育士を残していくように、残っていただきたいということで、１０番のところですね。新しい事業者にも区のほうから働きかけをしていくということですけれども、これは職員４１人全員ということでしょうか。また、議会では区は関与しないというような答弁でしたけれども、この保護者会で行っている回答の方針でやっていくということでいいのか、伺いたいと思います。"},{"i":123,"speaker":"竹田保育課長","text":"まず、区のほうから、保育の質の確保を最大限に考えまして、直接園長に指示したいというふうに申し出ましたが、そういう申し出が、相手方法人との間に、合意を得られなかったということでございます。\nそれから、計画を中止したというところですが、関西の芦屋市と、横浜市でも計画を中止したというふうに聞いております。\nそれから、保護者のご心配ということですけれども、やはり不正流用等が複数、今、報道されております。保育には問題はないのですけれども、そういった経営陣が経営している法人ということについて、保護者の方、ご心配はあろうかと思いますので、今回の決断をしたということでございます。\nそれから、雇用関係については、先ほど申し上げたとおり、基本的に私どもが話す立場ではないのですけれども、新しい事業者と十分話し合っていきたいと考えております。\n以上です。"},{"i":124,"speaker":"のだて委員","text":"保育園の建設中止があったところの芦屋と横浜であったということですけれども、その理由もつかんでいれば教えていただきたいと思います。\nそれと、保護者に心配をかけないように、経営陣がやはりこういった不正を行ったところで、心配をかけないようにしていくためにということでしたけれども、この、１年で事業者が変わってしまうというところでも心配はあると思うのですが、そこはやはり経営陣のほうの心配のほうが大きいという判断で、今回の事業者交代ということになったのか、伺いたいと思います。\n職員に残ってもらいたいという働きかけのところ、これは、現在、４１人の職員がいるということだったのですが、その全員かということもお聞きしたので。あるいは、保育士だけということになるのか、そこのところを教えていただきたいと思います。"},{"i":125,"speaker":"竹田保育課長","text":"まず、他自治体の撤退した理由ということですが、明確に先方には確認しておりません。\nそれから、信頼関係。今回、決断した理由でございますが、まず１つは、今後５年間、信頼関係を築いていくのは難しいというふうに考えたことと、それから来年、今年度で契約を終了するに当たっては、来年４月から新しい体制を築くには、早く決断する必要があるというところで、今回の決断に至ったものでございます。\nそれから、職員については、次の事業者が決めることでございます。"},{"i":126,"speaker":"のだて委員","text":"職員は事業者が決めるということですけれども、それもあると思うのですが、働きかけは、区のほうからしていくのは全員かというところでお答えいただければと思います。\n事業者の交代のところで、来年４月にやっていくために、早く決断したということですけれども、やはりそういったところも、ほかのところでは、港区では不正が発覚しておりますけれども、そういったところでは違約金を払わせて、事業を続けていっているところもありますけれども、そういった中で、契約解除に至った、これまでも少し説明がありましたが、そこの考え方を、もう少し詳しく教えていただければと思います。\nあと、ぜひ、芦屋や横浜で建設中止の動きになった理由も、それは情報をやはりつかんでいっていただきたいと思いますので、それは要望しておきます。\n保護者会の資料のところの６番のことですが、回答で、厳正かつ慎重に審査をしていくということですけれども、今回、このひろまち保育園のところと、これから行っていくところで何が違うのか、具体的にご説明いただきたいと思います。"},{"i":127,"speaker":"竹田保育課長","text":"まず、雇用関係にある、働いている者でございますが、全員かどうかというご質問ですけれども、まだ新しい事業者が決まっていない段階ですので、今、言及することは避けたいと思います。\nそれから、港区の事例でございますが、港区は現法人が直接運営する私立認可保育園、こちらは区立の業務委託による保育園ですので、基本的に施設の性格が違うと考えております。\nそれから、今後の公募でございますが、より慎重に、基本的なやり方、選考方法に問題はなかったと考えておりますので、同様の内容で実施していきたいと考えております。"},{"i":128,"speaker":"のだて委員","text":"選考方法は問題がなかったということで、同様にしていくということですけれども、そうしたら結局、厳正、慎重にということですけれども。つまりは、できるだけ気をつけていくと。気持ちの問題でしかないと思うのですけれども、それでは繰り返されない担保にならないと思うのですが、どう、この事業者交代が繰り返されないようにしていくのか、担保はあるのか伺いたいと思います。"},{"i":129,"speaker":"竹田保育課長","text":"委託というのは、あらゆるリスクを抱えている手法ですが、選考方法に問題はないと考えておりますので、このやり方でやっていきたいと考えます。今後も、万が一、不適切な場合は、強い気持ちで臨んでいきたいと考えています。"},{"i":130,"speaker":"のだて委員","text":"民間委託であらゆるリスクがあるということでしたけれども、それであれば、やはり、つまりはこれから毎年もしかしたら事業者が変わるかもしれないと、そういうことも、リスクもあるということだと思うのですが、やはりそれでは、これまで品川区立として質の高い保育を保ってきたという中で、保育の質を保てないと思うのですけれども、いかがでしょうか。"},{"i":131,"speaker":"齋藤子ども未来部長","text":"ちょっと何か誤解が生じてしまったかもしれません。違う意味で言ったと思うのだと思うのですけれども。\n１つ、保育の質について。我々も近場ではいますし、定期的にお話し合いの場も持ちました。現在を含めて、保育士、ひろまち保育園で、保育について、質の問題で問われることは一度もありません。今の体制も、３月までに守っていきたいと思っています。\n新しい業者の選定に当たりましては、手続き的なものはもちろん、変える考えはありませんけれども、業者の方と話し合いの場を持つ、あるいは周辺の状況、事情についてもいろいろな形で収集すると、こういった姿勢で向かって、同じようなことが繰り返されないようにというふうに考えておりますし、また、不正流用するという事業者が手を挙げるということは、今回の我々の、何度も何度も厳しいチェックをし、こういう解除に向けた対応もしたということもございますので、そういった事業者は来ないものだと思っております。\n加えて、幾つかの事業者の方から言われていますのは、品川区は前から保育について力を入れ、プライドを持っているから、細かいところまでをチェックし、ほかの自治体であれば見逃したところも見逃さなかった、また、見ても見ないふりをしたかもしれないけれども、そういった対応をしたのは、大変英断であると、こういった声を幾つかからいただいておりますし、こういった期待に応える保育というものを、品川区として積み重ねていきたいと思っております。"},{"i":132,"speaker":"のだて委員","text":"質の問題はないということですけれども。やはり、あらゆるリスクがあるということは変わらないと思うのですね。それで、今回のことがあったので、不正する事業者が来ないという考えだということですけれども、本当に来ないかはわかりませんよね。来たときに、しっかりチェックすることができるのかということだと思います。やはり、同じやり方でやっていく中で、この事業者変更というのが繰り返されない担保というのが、何もないと思うのですが。気持ちだけではなくて、しっかりやっていく、それだけではなくて改善が必要だと思うのですけれども、いかがでしょうか。"},{"i":133,"speaker":"齋藤子ども未来部長","text":"今回の事業者を変更したこと、合意解除に至ったこと、これは正しかったと私は思っております。それは委員もご理解いただけると思います。ただし、それでリスクというイメージで言うと、多分、保育課長が言いたかったのは、保育の必要なお子さま方を抱えておりますと、公立であろうと私立であろうと、さまざまな面で大変なこともあります。お子さまの状況も違いますし。そういった面で、私立の活力を使おうが、公務員で全員でやろうが、そのリスクの面では同じなのです。\nしたがいまして、今回からも事業者に対してさまざまな発信もできましたし、品川区ではさまざまな取り組みをして体制も強化しておりますので、担保という面では、十分、今回の事案を通して広く発信できたのだと思っております。"},{"i":134,"speaker":"のだて委員","text":"公立だろうがリスクは変わらないということでしたが、そんなことはないと思うのですよね。これは、事業者が変わるということは、公立にすればあり得ないわけですね。こういったことは行われないわけです。\n担保は何か、発信したことによって保たれるというようなご回答でしたけれども、やはり、具体的な改善を行っていかなければ、これが繰り返されないということは言えないと思いますし、保護者の方も納得できないと思うのですね。\nそれで、おそらくこれを聞いてもまた同じ答えだと思うので、ちょっと不正のことについてもお聞きしたいと思います。\n今、不正受給はなかったということですけれども、その根拠に、開設準備金のチェックをしたという答弁ですが、看護師の配置がされていなかったのは事実だというところで、看護師の配置というのは、開設後の運営費のことだと思うのですけれども、運営費のチェックはしたのか、伺いたいと思います。\nそして、この間、不正がない理由として、もう１つ、誤ったり偽ったりした報告がないということも言われておりますけれども、配置がない看護師分の運営費、受給しているとしても、正直に話せば不正ではないということでしょうか。"},{"i":135,"speaker":"竹田保育課長","text":"ただ、看護師の未配置の件でございますが、４月の当初から定員が見つからないということで、求人中との報告を受けております。\nそれから、運営費についても適正に使われているかどうかというのは、確認してまいると考えています。"},{"i":136,"speaker":"のだて委員","text":"運営費のチェック、今ちょっとよく聞こえなかったのですが、したのでしょうか。それとも、していくというご答弁だったのか、それを確認したいと思います。\nそして、不正がない理由、偽ったり誤ったりしたことがないというところで、先ほどもお聞きしましたが、事実を話せば、実際に不正をしていたとしても、不正ではないと。配置されていないけれども、運営費をもらっていたということを正直に話せば、不正ではないというお考えなのか、伺いたいと思います。"},{"i":137,"speaker":"竹田保育課長","text":"事実を報告していただいておりますので、それを事実を隠したということになれば、不正だと思いますが、事実の報告に基づいて報告していただいていますので、それを不正とは呼ばないと考えております。\nそれから、運営費については、現在も確認しておりますし、今後も確認してまいります。"},{"i":138,"speaker":"のだて委員","text":"看護師の配置が、今、チェックしているところだと、していくということでしたけれども。この間、不正がないと言いましたが、これからチェックしていくということなので、しっかりそれはチェックしていただいて、事実の報告であれば不正ではないということでしたが、普通に考えれば、本来、配置しなければならない看護師を配置していなかった。その分の運営費を受給していたとなれば、私は不正だと思います。区民の理解も得られないと思いますが、やはり不正があったということでよろしいのか、伺いたいと思います。\nそして、契約解除の理由ですけれども、保育方針の違いと、姫路市での不正受給の点で納得いく説明がなかったということでしたけれども、先の一般質問でも、このことを質問されてご答弁ありましたが、保育などの継続業務は１つ１つを理由に挙げて解除はできないという趣旨の答弁がありましたけれども、幾つも、つまりは、保育の方針の違いがあったということだと思ったのですが、どこが相入れなかったのか教えていただきたいと思います。"},{"i":139,"speaker":"あくつ委員長","text":"ご答弁の前に。構わないのですけれども、もう３０分近く１人で質問されてらっしゃるので、そろそろまとめて。"},{"i":140,"speaker":"竹田保育課長","text":"看護師の件でございますが、今、こちらのひろまち保育園は、１歳児園ですので、設置の義務等はございません。今後については、清算等も含めて、事業者と協議してまいりたいと考えております。\nそれから、具体的に相入れなかったことは何かということですが、日々、運営する中で、細かいことを挙げれば、日々の記録の様式とか、備品の配置等、さまざまなことがございます。たびたび、方針に関するやりとりをしていく中で、意見の相違が出ての結果でございます。"},{"i":141,"speaker":"のだて委員","text":"看護師の配置は、基準では義務ではないということですが、区が求めている、仕様書の中でも求めているものですので、やはり配置されていなくて運営費を受給していれば、私は不正だと思います。\n契約解除の理由ですが、いろいろ話し合いをしていく中で出てきたということですけれども、ぜひ、具体的に、これまでグループ保育ですとか、ご答弁ありましたけれども、ほかに何が相入れなかったのか、伺いたいと思います。\nそして、この間、保育を実施してみなければわからないというような答弁もありましたけれども、やはりそれでは、これまでのやり方ではチェックができないということだと思うのですけれども。これは、つまり事業者にだまされたということになると思いますが、この認識はどう捉えていらっしゃるのか。\nそして、最後に、今回、１年で契約を終わらせることということになりましたけれども、これは、先ほどのご説明だと、７月に法人が撤退することを決定したと。その後に、合意解除がされたということですので、法人のほうから、この契約を終わらせたいという問いかけがあったのか、伺いたいと思います。"},{"i":142,"speaker":"あくつ委員長","text":"今の、再度申し上げますけれども、最後ということだったので、これは最後ということで。"},{"i":143,"speaker":"齋藤子ども未来部長","text":"何か、事業者にだまされたという、私どもとしては、とても承諾できないご発言がありました。方針の違いです。繰り返します。方針の違いです。例えば、グループ保育でも、区の中でも、やる園長もいれば、やらない園長もいます。３カ月たってグループ保育をやめる園長もいます。やめないで継続する園長もいます。それは園長の裁量なのです。区からのＯＢだって、園長の裁量を生かしてほしいというのが我々の言い分であって、それも相入れないという小さいやりとりがあって、それでなかなか相入れなかったのです。それで、受け入れられないのであればどうしますかと、我々が、合意解除しますかという問いかけに対して、理事会で議決をしたと。そういうことでございます。\n細かいことを拾って解除などできないのです。よろしいですか。それで、小さいことを積み上げて、こういったことを改善してください、いかがですか、承諾いただけませんか、といったやりとりを繰り返して、そうやって信頼関係が破壊されて初めてできる。うちのほうで、勝手に解除します、ここで納得しないからだめです、というと、１７９人の子どもは、次の日から路頭に迷ってしまうのですよ。そういった、保育とは何であるか、保育の自治とは何であるかということを踏まえてのご質問で、ぜひお願いしたいと思います。ですから、だまされたということは、断じてございません。"},{"i":144,"speaker":"のだて委員","text":"では、最後で。"},{"i":145,"speaker":"飯沼委員","text":"だって、答弁によるから。"},{"i":146,"speaker":"あくつ委員長","text":"そうですけれども、一応、委員会の運営なので。お気持ちはわかります。発言のご自由もありますけれども。では、最後の１問ということで。"},{"i":147,"speaker":"のだて委員","text":"区立のところでもグループ保育をやるところとやらないところがあるというところで、だまされたわけではないというお話もありましたけれども、それであれば、やはり、１つ１つの細かいことの違いがあったということですが、それをしっかり、やはり明らかにしていくべきだと思います。そうしなければ、やはり事業者交代というこの事態が繰り返されないようにしていくことはできないと思いますので、改善をしていっていただきたいと思います。\nそして、この請願についても、やはりこの事態を明らかにしてほしいということと、やはりリスクは公立でも私立でも変わらないというお話でしたけれども、やはり公立にすれば事業者が変わることはありませんので、この区立認可園にしてくださいというところも、ぜひ、私としては賛成し、採択を主張していきたいと思います。"},{"i":148,"speaker":"あくつ委員長","text":"ご意見で。"},{"i":149,"speaker":"のだて委員","text":"はい。"},{"i":150,"speaker":"鈴木（博）委員","text":"平成２６年６月に、姫路市で経理の不正があった、補助金の不正流用の疑いが生じたというようなことが発覚したということで、ここの事業者と、やはりどう対応するかというのが、１つの、要するに直面した問題だと思うのですけれども。そこで、品川区のほうで、もうこの事業者とはできないと。契約解除に向けて決断したということは、非常にこれはやはり評価できるかなと。\nただし、さっき齋藤部長がおっしゃったように、すぐやめたら、結局、そこで今いる子どもが全部人質になっているので、どんな扱いをされるかわからないというのは、要するに子どもを守らなければいけないということが、最大配慮しなければいけないことだから、その間、うまく軟着陸、ソフトランディングできるように、いろいろと向こうと話し合いもして、最終的に３月に円満というか円滑に手を引いてもらおうと。その間は、最大限子どもを守ってもらう。今の質を高めて、今の質のままでやってもらうというようなことで、今回、落ち着いたということは、おおむね了解できるのではないかと思うのです。\nこの保育園の事業者に関しては、大学などもそうですけれども、ああ、立派な大学を運営しているから、経営陣もすばらしいかというと、そうでもないので。だから要するに、経営と、それから実際にやっている業務というのは、やはりある程度違うと思うのですよね。だから、この業者が保育に関してきちんと質が高いことをできているのだけれども、ただ、経営陣という、要するにいろいろと母体のところで問題がある業者だから、やはり信頼関係がそこでなくなりますから、そうすれば、後から後からいろいろなことを言っても、向こうも言ってきたりということも起こるかもしれないから、継続している自治体もあるみたいなのだけれども、そこでもう、ここで切りますということは、僕は非常にいい決断ではないかなと思って、今、話を聞いていました。\nただし、ちょっと１点だけ納得できなかったことは、やはりこういう業者を選んだところに関しては、途中で切らなければいけなかったということは問題なのであって、新しい業者を選定するときに、全く同じやり方を踏襲しますというのは、やはりいかがなものかと思うのですよ。そうすると、やはり繰り返しということも起こる可能性があるので。\nただ、今回、僕が思うに、品川区の場合は性善説に立って、手を挙げる業者はみんなすばらしい、保育に向けてしっかりとしている業者ではないかという前提で、いろいろ考えたところに、多少、いろいろチェックしなければいけない穴ができたのではないかというような気もするのですが。新しい業者を今度選定する上で、前回選定したときに加えて、どういう点をプラスで考えていかなければいけないかということに関しては、やはり一言、ご説明が必要だと思うのです。その点に関してお伺いいたします。"},{"i":151,"speaker":"竹田保育課長","text":"新しい事業者の選定につきましては、より厳正に、より慎重に、十分時間をかけて、しっかりと選定していきたいと考えます。"},{"i":152,"speaker":"齋藤子ども未来部長","text":"今、鈴木博委員におっしゃっていただいたことが、まさに私たちがこの間、取り組んで努力したことでございまして、合意解除に向けて、向こうも紳士的に応じていただきました。我々も、相手の非を責めたてるのでは、非があるとか、うちの区としての、ということではなくて、子どもたちのために何が主点であるかということを考えて、対応していただいたところでございまして。ただ、今、合意解除をしただけで、本当に３月末まで、本当に今の質が保っていただけるかというのを、またこれからは我々と事業者で、お互い十分に話し合いをして、信頼関係、継続と。先ほどから、なくなったと言っておきながら、ちょっと矛盾した言い方になりますけれども、３月まではいい関係でいたいと思っております。\nもう１つ、新しい業者を選定するときですけれども、選定するに当たって、十分なリサーチ、話し合いということが、１つ、もっと加えなければいけないのが１つと。今回、ぜひ、事業者の方に聞いていきたいのは、保育の引き継ぎという点で、どういったお考えがあるかということ、そういった点について、いろいろご提案もあると思いますし、うちも考えがございますので、この場ではちょっと差し控えさせていただきますけれども、その点で、担保というふうに、チェックというふうに、新しい項目というふうに考えているところでございます。"},{"i":153,"speaker":"鈴木（博）委員","text":"そうですね。あとは、それに加えて、こんなことが起こるはずがないというような、例えば不正経理みたいなことが、今回発覚したので、やはり、起こるはずはないだろう、こういうことはないだろうと思いながらも、やはりその点の追及というのも、しっかりお願いしたいと思います。"},{"i":154,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":155,"speaker":"あべ委員","text":"まず教えていただきたいのが、新しい事業者の選定スケジュールなのですが、既に公募説明会は終わっていると思いますが、現段階でどの程度の事業者さんが、今、締め切りはまだ来ておりませんけれども、関心を示してくださっているか。あるいは応募しそうかということは、わかれば教えてください。"},{"i":156,"speaker":"竹田保育課長","text":"今回の選定に関しましては、より厳正に行っていきたいと思いますので、数字については現段階での発表ではなく、決まった後にご報告させていただきたいと考えております。"},{"i":157,"speaker":"あべ委員","text":"わかりました。それでは、時期が来たらご報告をお願いいたします。\nそれで、今回の合意解除なのですけれども、確かにコンプライアンス上の問題ですとか、保育の方針の問題ですとか、やはりさまざま課題があったということです。それは、例えば大きな事故があったとか緊急的なことではないので、区としてはこれを、先ほどもおっしゃったみたいに、片目をつぶってやり過ごすということもできたのでしょうけれども、あえて、より高い信頼関係、より高い保育の質ということを求めてのことと思いますが、合意解除に、契約解除に踏み切ったということは、それはそれで品川区の姿勢を示すものであると、私は考えております。\nただ、やはり、先ほども別の委員からもありましたけれども、５カ月で撤退が決まるというのは、決して望ましいことでないというのも確かです。そういった意味では、やはり、今後、選ばれる事業者さんには、残りの任期をきちんと運営していただける、信頼関係をもって、お互いに運営できるような、そんな事業者さんを選んでいただきたいなと思います。その意味では、仕様書の部分、あるいは契約の部分はもちろんなのですけれども、やはり保育や運営に対する思い、あるいは保育士さんに対する処遇の考え方など、そういう価値観の部分もぜひ共有するようなプロセスが、私は必要だと思うのですが。今回の選定に当たっては、そうした部分というのはお考えでしょうか。"},{"i":158,"speaker":"竹田保育課長","text":"これから、審査あるいは仕様書等の提示等が、今後あるわけですけれども、事業者に誤解の生じないような綿密な打ち合わせを行うことによって、しっかりと対応していきたいと考えております。"},{"i":159,"speaker":"あべ委員","text":"その部分は、この議会での説明だけではなくて、保護者の方や区民の皆さんに対する疑問に答える部分でもあると思いますので、やはり、今回こういうことがあったけれども、次回はさらにこういう部分を加えますということを明確にメッセージとして出していかないと、何だか前回と一緒では、また同じことが起こるのではないかという疑念を抱かせてしまいますので、そこはやはり、区としても、さらにこういうところに気を使うというメッセージとしてわかりやすい言葉で出していただきたいと思います。再度お考えを伺いたいと思います。"},{"i":160,"speaker":"竹田保育課長","text":"新しい事業者の決定が１０月を予定しております。それで１１月には、決定後、また次回の保護者会を開きたいと考えておりますので、そういった場を通して、保護者の方にも十分に説明していきたいと考えております。"},{"i":161,"speaker":"あべ委員","text":"ありがとうございます。今回の請願の形に沿ったことで申し上げますと、このような契約解除という、余り行われないことがあって、不安に思う方、疑問に思う方がいる、それはそれで、私、当然だと思っております。その背景には、やはり品川区の区立保育園の保育の質というものへの信頼感というものもあるのかなというふうに思っております。ただ、私立保育園に関しましても、長く品川区の中で高い水準を築いてきた実績があるわけで、ただ、近年の保育園不足を背景に、一部の民間の事業者の中には、急拡大をする中で、保育の質がおろそかになったり、あるいは新規開設のための原資確保のためでしょうか、人件費や運営費を過剰に削ったりというような法人も、あるいは事業者もあるやに聞いております。要は、区立に比べて、私立あるいは民間というのは、どうしても玉石混淆になりやすいという面がありますので、でもそれは、民間が全ての区立よりも質が低いという意味ではないと、私は思っております。その意味で、区は民間の事業者に保育を任せるのであれば、その目ききと言ったらいいのですかね。やはり、いかに選ぶかということが非常に重要になってくると思っております。今後、品川区として、今、民営も随分増えてきておりますけれども、公設民営ということを考えていくのであれば、公立としての資質、私立園として求めるレベルと、公設園として、区立園として運営に求める保育の質や、あるいは人事管理の内容、そういったものがどう違うのか、あるいは違わないのかということを、きちんと整理した上で事業者に提示していく必要があるかと思うのですが、その点についてはいかがお考えですか。"},{"i":162,"speaker":"竹田保育課長","text":"公立の保育の答えというのは１つではないと思います。いろいろな手法があろうかと思います。公立で培ってきたもの、それから私立園で培われたもの、そういったものを融合させて、より高いレベルの保育を実施して、公設民営を通して実施していきたいと考えております。"},{"i":163,"speaker":"あべ委員","text":"総論としてはわかるのですが、今のでは、ちょっと質問のお答えとしてちょっとずれている部分があります。今のお答えでは、先ほど、別の質問に対する答弁にあった、私立園に求めるものと、やはり区立園として守るべきものというのが違うのだと。そのお話はちょっとかみ合わなくなってしまうのです。要は、ここはもう既に品川区の中には、区立の園もあり、私立の園もあり、私立の中にも社会福祉法人があり、あるいは株式会社ありと、いろいろな形態で保育が行われているわけですが、その中で、私立園と公立の、要は区立の民間委託とでは、区は、何か違うものを求めるのか、全く一緒でいいのか。あるいは、公設民営を行うと考えたときに、そこに何を求めるのか。全く公立並みの内容を求めるのか、私立の運営なのか。融合するというときに、どこは譲れなくて、どこは任せるのかということは、これはぜひ整理しておくべき問題だと思うのですね。今回の合意解除でも、ここは創意工夫でいいけれども、ここはやはり区の考えるとおりにやってほしいというのがあったからこそ、保育の方針の違いというのが生まれたのだと思うのです。だから、公立園には、区立園には、例え委託をしても、ここは守るべきことなのだということは、区としてきちんと整理しておくべきだと考えるのですが、いかがでしょうか。"},{"i":164,"speaker":"竹田保育課長","text":"おっしゃられるとおり、保育を実施していく中で、譲れる部分、譲れない部分というのはあります。今まで、公立で培ってきた経験をもとに、保育というものがあろうかと思いますので、今後、そういった面で整理して、今後の運営委託に生かしていきたいと考えております。"},{"i":165,"speaker":"あべ委員","text":"よろしくお願いします。"},{"i":166,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":167,"speaker":"新妻委員","text":"ご説明ありがとうございます。既に、このひろまち保育園の件に関しては、文教委員会でも報告をされておりますし、再度、今日、請願が出たということで、改めてご説明をいただき、また流れの確認をさせていただきました。私も、ほかの委員がおっしゃったとおり、最後にチェック機能というのが必要であろうかなというふうに思います。保育、待機児童対策を進めていく中では、やはり民間の手も必要だと思っておりますけれども、その上で、品川区がどうチェックをされるのかというところも、また必要な視点かと思います。この保護者会における書面の中で、今後のスケジュールが明確に公表されておりますけれども、既に公募の説明会が終わって、第１次審査会が始まるという流れになろうかと思います。具体的に今、数は課長のほうからは明言がありませんでしたが、手が挙がっているところがあろうかと思いますが、今やっているこのチェックの体制ですね。チェックするというところで、今されている、第１次審査会を迎えるに当たって、今されている具体的なチェックの内容ですかね。そういうところがもしお答えいただけるところがありましたら、教えていただきたいと思います。"},{"i":168,"speaker":"竹田保育課長","text":"今現在は、公募された事業者から書類の提出を受けて、その内容について各委員が中身についてチェック、吟味しているところでございます。委託に、任せられる事業者なのかどうかということを、今、書類を通じて確認しておりますので、その確認を通して、適切な事業者かどうかというのを確認してまいりたいと思います。今後も２次審査等控えておりますので、そういったあらゆる場を使って確認していきたいと考えております。"},{"i":169,"speaker":"新妻委員","text":"ありがとうございます。確かに、先ほどおっしゃられた別のご答弁ありましたけれども、品川区、保育の質が高いという、そういう講評がありますが、やはり見方として、大丈夫だという見方ではなくて、何か心配な点はないのかという、そういう視点で新たにまたチェックしていただきたいと思います。その上で、この選定会議というのが最終決定になると思うのですけれども、この選定会議で決定をする方々というのはどのような方で決定をされているのでしょうか。"},{"i":170,"speaker":"竹田保育課長","text":"選定会議のメンバーですが、副区長を筆頭に、部長、課長で構成されております。"},{"i":171,"speaker":"新妻委員","text":"ありがとうございます。それでは、このことをまた教訓にしながら、本当に、一番子どもたちを守っていく、保育の質を高めるということが一番でありますので、そういう視点でまた、再度、選定をお願いをしたいと思います。"},{"i":172,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":173,"speaker":"飯沼委員","text":"幾つかお伺いしますけれども。先ほどの部長のたびたびの答弁を伺っていると、区にも、事業者にも問題がなかったのだ。そう受け取れてしまうのですよね。私、きのう一般質問させていただきました。終わった後に、議場にいた他会派の議員さんからも、なぜ契約が解除されるのか、理由が全くわからないと何人かに言われました。あと、傍聴にいらしていた方からも、何で契約解除するほどのことがあったのか、全く中身が、質問しても答弁になっていないじゃないかという、こういう反応をいっぱいいただきました。子どもたち、そして保護者、そして職員の方々に不安を与えて契約解除となったわけですけれども、一体、この契約解除の理由、何だったのか、私はぜひ、区に、議会と区民に明らかにすべきである、その責任があると思うのですが、まず、たびたびの保育方針の違い、これ、一言に言ってしまっているけれども、一体何なのですかね。この間の、選定のプロポーザルの中身にも、しっかりと認可保育園を運営するために必要な経営基盤、および社会的信望を有している事業、そして区の保育行政をよく理解し、これはプロポーザルの実施要領なのですよ。区の保育行政をよく理解し、積極的に協力をする事業者であること、保護者はもとより、地域との信頼関係を築ける事業者であること、社会福祉事業に熱意と見識を有し、良好な実績のある事業者であること、これで選んだのですよね。チェックミスはなかったのですかね。あと、職員配置のところで、常勤看護師を１名配置していただきますと、きちんと書いてあるのですよ。探していたけれども見つからなかった。厳しいので、探しているさなかですと。報告があったから、それで、報告すればいいのですかね。私、はっきり言って悪質だと思います。区立の保育園だったら、看護師が必要なのにいなかったら、今の状態だと、派遣でも、とにかく何でも子どもたちの健康を守るために、探してきますよね。それが４月からずっと、探したのですけれども厳しいので見つかりませんでした。報告があったので問題はないですって、これは通用しないのではないでしょうか。私は悪質だと思います。１人の給与を考えたら、何カ月間不在のまま。これは、お金にシビアに考えたら、どうなのですかね。私は悪質だと思いますね。これが１点。なので、ちょっと看護師がいなかった問題は、重大な問題と捉えて、やはりきちんとなぜだったのかと反省もして、もちろんそうですが、再発防止のための手立てが必要だと思います。看護師の件が、１点です。\nあと、保育の方針なのですけれども、保育園の運営のしおり、理念とかが分かるものをくださいと言ったら、これしかありませんと、課長さんから届きました。ひろまち保育園の、保育園のしおりです。すごく立派な理念が書いてあるのですよね。子どもの最善の利益を考慮し、利用者主体を根幹に、行政、地域、保育園の緊密な連携を強化し、地域の子育て支援事業の核となると書いてあるのですよね。ひろまち保育園は、品川区初の公設民営保育園で、園児数３００人という大規模保育園ですが、品川区が大切にしてきた子育てのノウハウと、法人の持つ保育理念を融合させて、１人１人を大切にした保育を行います。これ、夢工房の理念ですよね。これに基づいて、だから契約前、プロポーザルの要領で確認をし、話し合いをして積み重ねて保育園は開設して、こういった中身に一致していたにもかかわらず、何が違っていたのですか。保育方針の違いって、私、きのうも具体的に教えてほしいと言ったのですけれども、何も出なかったのです。保育方針の違いって何なのでしょうか。"},{"i":174,"speaker":"あくつ委員長","text":"質問でよろしいですか。"},{"i":175,"speaker":"飯沼委員","text":"はい。"},{"i":176,"speaker":"竹田保育課長","text":"まず、看護師の問題でございますが、今、公立でもなかなか看護士を募集しても定数を採用できないという状況で、非常に厳しい状況でございます。おそらく、専門性を保育園では高められないというご不安があるのかもしれません。看護師を採用するというのは、今、非常に厳しい状況だということを踏まえて、求人中という報告を受けているところでございます。\nそれから、方針でございますが、委員おっしゃられるとおり、公立と私立を融合させて、より高い保育を目指してきたところなのですが、なかなか信頼関係が築いていけないという判断をしましたので、今回の結論に至ったところでございます。"},{"i":177,"speaker":"飯沼委員","text":"ここからちっとも脱していないのですよね。信頼関係が築けなかったというのはわかるのだけれども、何をもって信頼関係が築けなかったのか、その具体的な中身を聞いているのですよ。答えになっていませんよ。何回聞いても、同じ。信頼関係が築けなかった。もとがあるはずではないですか。品川区はきちんと方針を伝えていますよね。夢工房との、運営とか保育方針の違いが、どう対比して違っていたのかというのが、この間、何も出ていないのです。保育方針の違いって何ですか。契約解除になる決定的な問題ですよ。ここが全然明らかにならなくて、誰が聞いてもわからないと言っている状況の中で、信頼関係が築けませんでしたからやめますって、それでは私は納得しませんし、保護者の皆さんも区民の皆さんも納得できないのではないでしょうか。ぜひここを明らかにしてほしいと思います。\nあと、姫路市の説明が不十分。それで信頼関係が今後５年間、１年間は我慢できるけれども、５年間は無理だったのですということで、その姫路市のいろいろ問題の説明の不十分さというのは、区は何を求めて、それに対して不十分だったのか。ちょっとそこを含めて、保育方針の決定的な違いと、姫路市に求めた信頼関係が保てなかった向こうの説明、不十分だったところは何なのか、私はぜひ、ここの２つ、２点は具体的にお伺いしたいと思います。今日、これを聞くまでは終わりません。"},{"i":178,"speaker":"竹田保育課長","text":"保育方針の違いということですが、日々運営する中で、たとえば日々の大切な子どもの成長を記録していく様式ですとか、事故を起こさないような備品等の配置とか、扇風機の設置とか、その他もろもろ、聞き方によっては小さなことというふうにお考えになる方もいらっしゃるかもしれません。でもこれは、日々保育をしていく中で、とても大事な要素でございます。そういったもろもろのことに関して、お互いの見解の相違があり、それを埋められないというふうに決断したので、今回はこういった結論になったということでございます。\nそれから、姫路市の不正について何を求めたのかということでございますが、どういう原因で、どういう内容の不正があり、どういう再発防止策がとられるのかというような詳細の説明を求めたところでございます。\n以上です。"},{"i":179,"speaker":"飯沼委員","text":"姫路市の起こった中身、どういう中身だったのかという詳細を求めたけれども、何も出なかったわけですか。これで何を得たわけですか。私は、だから、契約解除に至るに当たっての、この中身ももちろん原因になっていると思うのですけれども、詳細を求めて、何がどう不十分だったのか、何がわかったのか、それが１つです。\nあと、保育方針なのですが、方針というよりも、保育の方法なのですかね。課長が言っているのは。１つ１つ、小さなことかもしれないと言っているのですが。大もとの基本的な大きな考えの違いというのはなかったのでしょうか。細かいことだけだったのですか。保育の方針って、もっとでっかいものだと思っているのですが。その辺の中身はどうだったのでしょうか。"},{"i":180,"speaker":"竹田保育課長","text":"姫路市の件につきましては、法人より文書の、お詫びという文書が届いておりますが、その内容については十分なものではなかったということで、今後、第三者委員会に協力して事実解明に努めていくという内容が主な趣旨でございます。ただ、こちらの求めていたものとは隔たりがあったので、さらなる説明を求めましたが、出てきていない状況でございます。\nそれから、保育の方針、私は小さいことというふうに申し上げたつもりはございません。そういうふうにお感じになる方もいらっしゃるかもしれませんが、というふうに申し上げたところでございます。保育の方針というのは、小さいことの積み重ねでございますので、その積み重ねた結果が相入れなかったということでございます。"},{"i":181,"speaker":"飯沼委員","text":"姫路のことをいろいろ聞いて、お詫びが届いたのですか。お詫びが届いたと聞いたのですが。区に対してのお詫びですか。保護者に対してのお詫びなのですか。ちょっとそういうのも中身がわからないのですけれども、十分でなかった。第三者委員会というか、機関に任せていくということなのですが、それ以上、区は、実際に聞いてわからなかったことで、ほかに調査をしてわかったこともあるのでしょうか。私もこの間、あちこちに問い合わせました。また、芦屋のほうからもいろいろな連絡もいただいたり、お隣の目黒、港、いろいろなところから夢工房の実態の告発が届いているのですが、区はそういった中身を捉えていらっしゃるのでしょうか。私、区にも法人にも何か問題なく、先のことを見通して円満解決なのですという考え方が、とても理解できないのですが、法人についてどの程度担当されているのかをお伺いします。"},{"i":182,"speaker":"齋藤子ども未来部長","text":"まず、ちょっと誤解があるかなと思ったところがあります。解除というものの考え方です。解除は一般的に解除事由があって解除するというのが、一般的な理解です。例えば、物を頼んだのに来なかったとか、払わなければいけないのを払わない。そういった事由で解除する、これは解除の事由というのがあります。今回、私どもがとったのは合意解除です。ちょっと例えがよくないので誤解を受けるかもしれませんけれども、円満離婚なのですよ。お互いに。我々は我々で、リスクマネジメントという点もありますし、向こうさん、法人さんは法人さんで、今後の企業運営としての選択が、集中というのがあったのかもしれません。聞いていないからわかりません。ただ、お互いの立場、思いがあって、合意解除が最善であろうということに達したわけでございます。\n個々、何があったか、何を言ったか、向こうは何なのだということで、２つ目なのですけれども、我々は、相手方の法人を糾弾する立場にはありません。それはしかるべき立場の人たちが、機関がやって、例えば兵庫県では、私立保育園の運営費に不正があったのだということで、第三者委員会というのを設けて、弁護士さん、公認会計士さんが、学術関係の方、その間の払いは法人に払わせるけれども、選任はうちでするよという、何か兵庫県らしいやり方だったらしいのですけれども。そういう形でいろいろ情報も収集してらっしゃるようです。夢工房も含め、目黒、港にあるところまで来られたというような話も聞いたというふうに伺っています。ただ、それを糾弾するのは、我々の立場ではありません。\nしつこいようですけれども、繰り返しますけれども、来年の３月まで大人の関係でいて、子どもたちを守るのが、我々の立場です。このことは、繰り返し申し上げさせていただきたいと思います。"},{"i":183,"speaker":"飯沼委員","text":"最後のところ、とってもひっかかりますよね。糾弾する立場ではなく、子どもを守る立場だと。子どもを守る立場ですか。これ。お互いの責任を不明確にして、先の、次の事業者を決めることが、子どもを守る立場なのでしょうか。私は全然違うと思いますね。\nあと、この夢工房のことは、全国で７都道府県なので、結構あちこちでいろいろ問題が起こっています。私はぜひ、この中身を把握したら、この事業者に問題がないなんて、とても言えないなと思うのですよね。本部が芦屋にあるのですが、一般質問でもしましたが、人件費の比率が４５％。際立って低いのですよ。これって、だから、保育士の賃金が低いということです。働いている皆さんを正しく評価しないで、言葉は悪いけれどもこき使っているということですね。人件費比率が低いです。\nあと、子どもの保育と無関係な、本部に上納する上納金、あと積立金、余剰金などが、総収入に対して異常に多いと言われています。このことは、品川の池田山のところで夢工房が保育園を開設しようと思ったときに、地域の皆さんから指摘されていた項目の１つでもあるのですよ。利益をいっぱい上げている。そういったことですね。\nあと、もう１つ。私があっちからもこっちからも聞いているのが、パワハラがある職場であるということなのですよ。私、これすごく重たいと思っています。理事長、あと身内の方から、職員に対するパワハラがすごく厳しい。私が知っている保育関係者は、大事な大事な子どものことを愛している保育士が、このパワハラで体が壊れてしまったって。１件ではありません。これでやめていく保育士がすごく多いのです。聞いてびっくりしたのだけれども、在職２年未満で６５％がやめているのです。\n私、ひろまちのことを言っているのではありませんよ。夢工房の法人の体質がどうであるかということを、ぜひ知っていただきたい。３年以内でほとんど退職するそうです。私、この根底にあるのは、パワハラももちろんなのですが、長く働かなくてもいい、保育士はさっさとやめてほしい。経験年数が少ないうちに、給料が上がる前にやめてほしいって。"},{"i":184,"speaker":"あくつ委員長","text":"飯沼委員。思いはよくわかりますけれども、そろそろまとめていただいて。"},{"i":185,"speaker":"飯沼委員","text":"済みません。でも、ここ、一番大事なところです。\n安上がりな若い保育士を使っているという、私は、この運営の主体、ここをしっかり捉えていかないと、選定の結果、あとで問題が生じましたので、変えました。私、さすが公立よね、民間ではこんなことあり得ないわよねという声も、たくさんいただきました。選定するということは、それだけ重いことですよね。私、運営方針の違いって、こういった日々のことにあるのではないか、ここが隠されているのではないか、私はすごくこれを思っていますが、私、ここ、隠さないでいただきたい。\nひろまち保育園は、１２人かと思っていましたが、さっき１３人ってお話が。品川区立の経験をされた保育士さんたちを、たくさん、いろいろな方法で集めた。ヘッドハンティングという方もいました。穴があいて大変だという意見もありましたけれども、その人たちが一生懸命、品川区の保育を実現させたい、ここで実現させたいともがいたから、よその夢工房の保育園のように、ひどい状態にはなっていないのかもしれないけれども、やはりここに根本の問題があるのではないかと、私は思っています。私、ここをブラックボックスにしていただきたくはない。私、ここを解明する、原因をしっかりと追究して、責任もどこにあるのか、あと、改善点な何なのかというのを、区がしっかりと示さないと、これからしっかり話し合っていきます、十分間違いのないようにやっていきます、信頼関係つくりますなんて、そんな言葉だけでは改善しません。この点をどうお考えでしょうか。"},{"i":186,"speaker":"齋藤子ども未来部長","text":"いつも同じような論法でおっしゃいますけれども、６５％、３年以内に離職して、７都道府県、二十数園、理論値として運営できないのですけれども。どこでお知りになりましたか。"},{"i":187,"speaker":"飯沼委員","text":"何ですか。"},{"i":188,"speaker":"齋藤子ども未来部長","text":"３年以内に６５％やめたら、理論値として単純に、私、今、計算できませんけれども、二十数園、運営できませんよ。だから、我々、しつこいようですけれども、相手方を糾弾する立場にはないのですよ。委託、業務委託契約で、パートナーですから。３月までは園運営をしましょうという関係でいますので、相手方法人を糾弾するのは兵庫県が設置した第三者委員会であり、しかるべき立場の機関だと思っています。\n合わせて本会議でもご答弁申し上げましたが、兵庫県と横浜市で特別監査がありました。その時点で、職員の配置、保育の状況、職員の処遇に特段の指摘はないと、これは我々も聞いておりますので、今、委員がおっしゃったこと、それが正しいという前提でご答弁する立場にもなければ、糾弾する立場にもないということは、繰り返しご答弁申します。"},{"i":189,"speaker":"飯沼委員","text":"２年間で６５％、３年間でほぼ全員という、３分の１ずつやめたら、３年間で入れかわってしまうのですよね。２、３年でほとんどの職員が入れかわるという。信じられないでしょう。\nだからそういう実態も含めて、調べていただきたいと思います。\nちょっと、資料もないのに言わないでくださいね。私は芦屋と都内の保育園のところから聞きました。実態って、保育の質って見えにくいし、実態を知るというのは、内部告発がないとわからないのですよ。そんなに簡単に外から見えてわかるものではありません。連絡を、十分な信頼関係がないと、中身が出てこないのですね。姫路の保育園の不正がわかったのも、普通の監査ではわからなかったそうです。内部告発です。実際に、そこの園のことを知っていて、この園長先生、理事長さんのお母さん、実在しませんよねという指摘があって、そこから調査があって、わかったということです。なので、普通の監査をしている限りにおいて、なかなか不正というのは見えにくい。でも、今回、品川区の保育園から移られた保育士さんたちの頑張りで、普通は目に見えないところがわかったのだけれども、そこが全然、表に出てきていないではないですか。現場で、現場の保育は問題ないというお話でしたよね。だから、理事長さんとかの方針と合わない保育で頑張っていたのではないかと。"},{"i":190,"speaker":"あくつ委員長","text":"そろそろ、２５分になろうとしておりますので、そろそろまとめて。まだご発言されていない方もいらっしゃる。ご発言されるかどうかはわかりませんが。発言されていない方もいらっしゃいますので、そろそろ。思いはよく伝わってまいりますけれども、まとめていただければ。"},{"i":191,"speaker":"飯沼委員","text":"はい。そういった面で、私は、だから、チェック、十分できていなかった。私は区の責任、あると思います。\nあと、契約をした中身と違う保育を実施していたというところでは、事業者の責任も明らかなのではないでしょうか。この点を、しっかりさせること、契約解除になった原因、そして私は、今回、区の失態であると思っています。責任がないなんてとんでもないと思います。原因を徹底的に究明し、区の責任を明らかにすることをなくしては、私は、幾ら言葉で尽くしても、同じ失態を繰り返していくと思います。ぜひ、この間、保育の質とかコストについて、検証をすると言っていますよね。私は、起きてしまってとても残念ですが、今回のひろまち保育園のことで、しっかりと検証し、この民営化について明らかにしていくこと、このことが大事であります。このことを抜きにして先に進んではいけないと思っています。いかがでしょうか。"},{"i":192,"speaker":"竹田保育課長","text":"区は、昨年７月に、事業者の選定を行いました。その時点では不正経理は全く想定できませんでしたし、区には、事業者選定に当たって調査権もございませんので、例えば事業者の事務所に行って情報を調べるといったようなことができません。当時、事業者選定に当たっては、できる限りの現場の保育を見に行くとか、当時できる限りのことを行っておりましたので、選定には区の責任はないと考えております。\nただ、今後の選定については、十分慎重に行っていきたいと考えております。\n以上です。"},{"i":193,"speaker":"飯沼委員","text":"区の責任はないというのが最後だったのですけれども。保育園って、本当、以前、経営の問題で突然閉園になってしまった保育園が幾つかあって大問題になったのですけれども、区立保育園って絶対にそんなことはあってはならないですよね。ないのが区立保育園だと思うのですよね。民間の法人とか企業がやるから、経営状態が悪かった、何かあったからというふうに投げ出して、閉園にしてしまうことがあるのかもしれないけれども、区立の違いって、やはりそこなのではないですか。子どもたちに徹底的に責任を持つ。私、これが区立と私立のところ。私立を否定しているわけではありません。学校法人とか社会福祉法人で、本当に子どもたちのことを第一に考えている保育園、私立の保育園、たくさんあります。でも、中には今回のような、私は夢工房、さっきだまされたんじゃないって言ったけれども、だまされたほうもだましたほうも、両方、原因があるからこんなことになったんだと思います。こういったところを選定してしまった誤りはしっかりと認めて、私は、改善をする、繰り返してしまいますが、検証が必要と思いますが、いかがでしょうか。"},{"i":194,"speaker":"竹田保育課長","text":"繰り返しになりますけれども、次の選定に当たっては、しっかりと調査して、現場も見に行って、それで選定していきたいと考えております。"},{"i":195,"speaker":"あくつ委員長","text":"ほかにご発言ございますか。"},{"i":196,"speaker":"高橋（し）委員","text":"もう議論がたくさんあったので、少しだけにさせていただきますが。もう先ほどから何度もご答弁いただいているのですが、残りの保育をしっかりするということと。\nあと、次の事業者を選定というか、引き継いでいく状況の中で、先ほどありました保育士さんたちの引き継ぎ分といいますか、継続した雇用といいますか、それを十分配慮していただくという。話し合っていきたいという表現でしたけれども、そこのところを、これは要望ですけれども、きちんとしていただきたいということ。\nそれで、かなり各委員の方から、選定についていろいろなお話が出ていたので、今回の事業者の次の選定については、先ほども十分に慎重にやるというお話がありましたけれども、ぜひとも、今、指摘があったことを踏まえて選定していっていただきたいと思います。\n１つだけですけれども、その後、やはり決まった後も、指摘や指導については、指定管理者だとモニタリング的なことがあって外に出てくるのですが、業務委託になると少し質が違うので、そのあたりについても、質というか、表現が違うのですけれども、そのあたりの違いの中で、どういうふうに指摘や指導をされていくかというのだけ確認したいと思います。"},{"i":197,"speaker":"竹田保育課長","text":"まず、残りの期間の保育でございますが、相手方理事長も、しっかり３月までは保育を行っていくということを明言されておりますので、３月まではしっかりとやっていただきたいと考えております。\nそれから、次の事業者の選定に当たりましては、スムーズな移行というのが、当面の最大の課題ですので、どういった引き継ぎ方法をやっていくのかということも、十分提案を受けながら選定していきたいと考えております。\nそれから、新しい事業者に移行した後でございますが、指導検査を行う部署がございますので、そちらを通して、しっかりと保育の状況をチェックしていきたいと考えております。"},{"i":198,"speaker":"高橋（し）委員","text":"今、最後のところで、指導検査の部署ですか。そこできちんと、こういったことにならないような形で、最終的にそごが出ないような形で、日常的にチェックのほうをしっかりしていただきたいと思います。"},{"i":199,"speaker":"あくつ委員長","text":"以上で質疑を終了いたします。\nそれでは、まず、平成２８年請願第１１号 ひろまち保育園の公設公営を求める請願について、ご意見を伺いたいと思います。継続にする、あるいは結論を出す、どちらか、自民党・子ども未来からご発言願います。"},{"i":200,"speaker":"鈴木（博）委員","text":"結論を出す。"},{"i":201,"speaker":"あくつ委員長","text":"公明党。"},{"i":202,"speaker":"新妻委員","text":"結論を出す。"},{"i":203,"speaker":"あくつ委員長","text":"共産党。"},{"i":204,"speaker":"飯沼委員","text":"結論を出す。"},{"i":205,"speaker":"あくつ委員長","text":"民進・無所属。"},{"i":206,"speaker":"あべ委員","text":"結論を出す。"},{"i":207,"speaker":"あくつ委員長","text":"高橋しんじ委員。"},{"i":208,"speaker":"高橋（し）委員","text":"結論を出す。"},{"i":209,"speaker":"あくつ委員長","text":"それでは、本件については結論を出すでご意見がまとまったようですので、そのような取扱いでよろしいでしょうか。\n〔「異議なし」の声あり〕"},{"i":210,"speaker":"あくつ委員長","text":"それでは、本件については結論を出すに決定をいたしました。\nそれでは、採決に入ります前に、本件につきまして各会派の態度を確認いたします。\nそれでは、自民党・子ども未来からお願いいたします。"},{"i":211,"speaker":"鈴木（博）委員","text":"不採択です。その理由は、要するに民設公営で、おおむね問題はないと思っているので。いろいろな多様なやり方を推し進める意味で、新しい立派な事業者を見つけて、今の区の子どもたちが安全に、このまま今の質の高い保育が続けられるようにお願いすることにして、とりあえず、この公設公営ということに関しては、不採択ということでお願いしたいと思います。"},{"i":212,"speaker":"あくつ委員長","text":"公明党。"},{"i":213,"speaker":"新妻委員","text":"不採択です。理由は、公設公営ということですけれども、今、ご説明をいただきましたとおり、今後しっかりとしたチェック機能をさせていただいた上で、民間の活力をしっかりと生かしていただきたいと思います。"},{"i":214,"speaker":"あくつ委員長","text":"共産党。"},{"i":215,"speaker":"飯沼委員","text":"意見は、賛成、採択を主張いたします。契約解除の原因を区民に明らかにしないまま、終わってしまってはならないと思います。今回の失態を反省をし、原因を徹底究明し、区の責任を明らかにすることなくしては、また同じ失態を繰り返すと思っています。子ども第一のことを考えたならば、ぜひ区立認可保育園にしていただきたいという、この願いは十分理解できます。そして、ぜひ原因を明らかにしていただきたいという立場で、採択を主張します。"},{"i":216,"speaker":"あくつ委員長","text":"民進・無所属。"},{"i":217,"speaker":"あべ委員","text":"まず、請願項目が２つありますが、この１つ目について、区立認可園に、公設公営にということですが、先ほども述べたように、公設公営でなければいけないという考えではありません。加えて、現在の保護者の方々が、今の保育士さんたちの雇用の継続を強く願っていらっしゃるということを考えても、ここで運営形態を変えるわけにはいかないと、私どもは思っております。これが１番です。\nそれから２番。契約解除、これはあくまでも、先ほどご説明があったように、合議の上の解除であって、合意による解除であると思っております。その原因としては、保育の方針並びに姫路等々での説明不足ということが挙げられておりました。それ以上に、例えば、先ほど糾弾という言葉もありましたが、逆に糾弾をするような姿勢であれば、これは合意解除ということは、私は不可能であったと思います。解除ができないと、契約を続け、子どもが通いながら、両者で厳しいやりとりをしなければいけないという状況は、一番避けなければいけない関係性であると思っております。私どもとしては、この原因ということは、まずは合意による解除が成立したということと考えております。\n以上の理由をもって、今回の請願には不採択とさせていただきたいと思います。"},{"i":218,"speaker":"あくつ委員長","text":"高橋しんじ委員。"},{"i":219,"speaker":"高橋（し）委員","text":"１番のほうですけれども、公設民営についてですけれども、これは公営民営の中で、区が先ほどの選定や指導のところで指導力を発揮していって、公設民営の方針のもとで進めていくのは、民間活力の導入にもつながることでありますから、１番のほうは不採択ですね。\n２番のほうも、先ほどのご説明で、原因については理解できましたので、不採択ということです。"},{"i":220,"speaker":"あくつ委員長","text":"それでは、平成２８年請願第１１号 ひろまち保育園の公設公営を求める請願について、採決をいたします。\n本件は、挙手により採決いたします。本件を採択とすることに賛成の方は挙手を願います。\n〔賛成者挙手〕"},{"i":221,"speaker":"あくつ委員長","text":"賛成少数につき、平成２８年請願第１１号は、不採択と決定いたしました。"},{"i":222,"speaker":"あくつ委員長","text":"続きまして、平成２８年度請願第１３号 ひろまち保育園を区直営の保育園にすることを求める請願について、ご意見を伺いたいと思います。継続にする、あるいは結論を出す、どちらか、自民党・子ども未来からご発言願います。"},{"i":223,"speaker":"鈴木（博）委員","text":"結論を出す。"},{"i":224,"speaker":"あくつ委員長","text":"公明党。"},{"i":225,"speaker":"新妻委員","text":"結論を出す。"},{"i":226,"speaker":"あくつ委員長","text":"共産党。"},{"i":227,"speaker":"飯沼委員","text":"結論を出します。"},{"i":228,"speaker":"あくつ委員長","text":"民進・無所属。"},{"i":229,"speaker":"あべ委員","text":"結論を出す。"},{"i":230,"speaker":"あくつ委員長","text":"高橋しんじ委員。"},{"i":231,"speaker":"高橋（し）委員","text":"結論を出します。"},{"i":232,"speaker":"あくつ委員長","text":"それでは、本件については結論を出すでご意見がまとまったようですので、そのような取扱いでよろしいでしょうか。\n〔「異議なし」の声あり〕"},{"i":233,"speaker":"あくつ委員長","text":"それでは、本件については結論を出すに決定をいたしました。\n採決に入ります前に、本件につきまして各会派の態度を確認いたします。\nそれでは、自民党・子ども未来からお願いいたします。"},{"i":234,"speaker":"鈴木（博）委員","text":"不採択です。理由は、先ほど述べたとおりです。"},{"i":235,"speaker":"あくつ委員長","text":"公明党。"},{"i":236,"speaker":"新妻委員","text":"不採択です。理由は、先ほどと同じですが、２０１７年４月から、区直営の公立保育園にというのが請願で、既に新しい民間事業者も選定を進めているところでありますので、不採択です。"},{"i":237,"speaker":"あくつ委員長","text":"共産党。"},{"i":238,"speaker":"飯沼委員","text":"採択を主張します。今回の夢工房の選定、私は、これは間違った選定をしてしまったと。民営化の問題が明らかに噴出した問題であると思っています。問題点としては、待機児解消のために、民間保育園にどんどん誘致している品川区に来てほしいと。どちらかというと、行政が事業者を選ぶのではなく、事業者が自治体を選んでいく、そういった方向に、今、なっていると思います。とにかく、数を増やしていきたいといった中での民営化ですので、こういった中身の中で、夢工房のような、はっきり言ってふさわしくない、品川区の保育を任せるにふさわしくない、公設民営にふさわしくない法人を選んでしまったというところにおいては、今回の選定の流れからずっと、しっかりと検証を行っていく必要があると思います。保育が安定し、保護者が安心して預けられる保育園になるためには、この検証ができていませんので、ひろまち保育園は区の責任で、区直営の公立保育園としてくださいという願いは十分理解できますので、採択を主張いたします。"},{"i":239,"speaker":"あくつ委員長","text":"民進・無所属。"},{"i":240,"speaker":"あべ委員","text":"不採択をいたします。理由は、先ほど述べたところと同様です。ただ、１つつけ加えるのであれば、今後、区が公設民営を進めていこうというのであれば、先ほども申し上げたように、どういった形で公設民営をしていくのか、あるいはどのような形で事業者を選ぶのかというのは、さらに精査をしていくということも必要であると思い、合わせて申し上げます。"},{"i":241,"speaker":"あくつ委員長","text":"高橋しんじ委員。"},{"i":242,"speaker":"高橋（し）委員","text":"不採択で。理由は、先ほどの公設民営についての内容と同じです。"},{"i":243,"speaker":"あくつ委員長","text":"それでは、平成２８年度請願第１３号 ひろまち保育園を区直営の保育園にすることを求める請願について、採決をいたします。\n本件は、挙手により採決いたします。本件を採択とすることに賛成の方は挙手を願います。\n〔賛成者挙手〕"},{"i":244,"speaker":"あくつ委員長","text":"賛成少数につき、平成２８年請願第１３号は、不採択と決定いたしました。\n以上で、請願・陳情審査を終了いたします。\n会議の運営上、暫時休憩いたします。\n○午後 ０時２８分休憩\n○午後 １時３０分再開\n────────────────────────────────────────────"},{"i":245,"speaker":"あくつ委員長","text":"ただいまより、文教委員会を再開いたします。\n────────────────────────────────────────────\n３ 報告事項\n(1) 専決処分の報告について（報告第２２号）"},{"i":246,"speaker":"あくつ委員長","text":"予定表３、報告事項を行います。\n初めに、(1)専決処分の報告について（報告第２２号）を議題に供します。\n本件につきまして理事者より説明願います。"},{"i":247,"speaker":"廣田子ども家庭支援課長","text":"それでは、私からは、報告第２２号、奨学金にかかわる専決処分についてご報告いたします。お手元にＡ４の資料１枚ご用意してございます。\n区奨学金につきましては、区奨学金貸付条例に基づきまして、奨学金借受人および連帯保証人に対し返還を求めております。返済の滞っている者に対しましては、以下のとおり督促を行ってまいりましたが、返還に応じない者が生じたため、地方自治法第１８０条第１項の規定により専決処分を行い、東京簡易裁判所に対し支払いを求める訴えを提起いたしました。\n概要についてご説明いたします。\nまず、本人および連帯保証人に対し、区より文書にて督促を実施しております。平成２７年７月３０日現在の滞納件数は２２５件でした。滞納金額にいたしますと２,７１１万円余でした。\nさらに、訪問督促を行っておりまして、平成１４年度からシルバー人材センターに委託しまして、品川区および近隣在住者に対しまして訪問督促を実施しております。訪問件数は、月おおむね１５０件で、年間１,８００件ほどでございます。\nこれらの督促にもかかわらず返還に応じない者に対しましては、平成２４年度より弁護士に債権回収業務を委任しておりまして、平成２７年分の委任件数は３３件でございます。滞納金額にして４９０万円余でございます。弁護士名による督促の発送は、平成２７年１０月３０日に発しております。\nさらに、弁護士による督促にもかかわらず、連絡のない者に対しまして、７月１１日に専決処分を行い、訴えの提起をいたしました。件数は５件となります。内容につきましては、裏面をごらんいただけますでしょうか。案件につきましては５件となっておりまして、被告１２名で、借受人５人、連帯保証人７人。金額にして２００万８,２００円となっております。５件に関しましては、全く連絡がないもの、または一旦連絡は来たけれども、その後、音信が不通になっているものなどの５件でございます。\n私からの説明は以上です。"},{"i":248,"speaker":"あくつ委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":249,"speaker":"のだて委員","text":"まず、文書督促のところで滞納件数が２２５件というところですけれども、この文書督促によって効果があったというか、連絡があって返済に結びついたというのは何件になるのか伺いたいと思います。\nそして、その次が訪問督促ということで、３番目としては弁護士の督促となっておりますけれども、この間で、電話での連絡というのはできたのか伺いたいと思います。\nそして、今、５件の方が残っているというところで、実態をつかんでいらっしゃるのか、それもお聞きしたいと思います。\n最後に、裏のところで、現況のところで、督促到達でとまっているところがあると思うのですが、ほかに分納不履行というのもあるのですが、これはどういう状況なのかお知らせください。"},{"i":250,"speaker":"廣田子ども家庭支援課長","text":"まず、１番目に、文書督促による反応でございますが、文書督促、訪問督促という順番に行っているわけではございませんで、文書督促も行いながら、随時、訪問督促も行っているということなので、具体的にどの対応により数字が落ちていくというわけではないのですが。反応が、電話等連絡がなくても、督促が行くことでお支払いになる方もいらっしゃるので、平成２７年７月３０日現在、２２５件滞納の件数があるのですが、平成２８年１月になると滞納の件数が１５０件というふうになっておりますので、そのままお支払いいただく方もおりますし、電話等の連絡が来る方もいらっしゃるという状況になっております。電話等の連絡をいただいている方もございますし、突然、来庁される方もいらっしゃいますが、数についてはちょっと、ぱらぱら見えるので、具体的な数については、申しわけございません。押さえてはいないということです。\nまた、あと、５件に対する実態でよろしいでしょうか。５件についてですが、実態といいますと、連絡はしたのですが、督促を出して全く連絡がなかったものは２件です。全く反応がなかったものが２件ございまして、その他につきましては、一度電話がかかってきたのですが、折り返して、やりとりをしたり、面接をしようとしたところで、電話も出なくなってしまった、文書による通知も受け取らないという。"},{"i":251,"speaker":"あくつ委員長","text":"これの意味はどうですか。"},{"i":252,"speaker":"のだて委員","text":"分納不履行と。"},{"i":253,"speaker":"廣田子ども家庭支援課長","text":"分納不履行につきましては、一旦、分納の申し入れを行って、納付書も送ったのですが、そのまま反応がないということで、分納の約束をしたけれども、約束をたがえたので提訴するという、そういう内容です。"},{"i":254,"speaker":"のだて委員","text":"分納不履行だと、１回連絡がとれたけれども、また払いが滞ったというところで、連絡もとれなくなってしまったということだと思います。全く連絡がとれないのが２件あるというところで、ほかの３件についても、現在は連絡がとれていないということで、この訴えの提起をしたと思うのですけれども、やはり、実際に払いたくても払えない方もいらっしゃると思いますので、そういった実態を、連絡ないというところではありますけれども、それをしっかりつかんでいただいて、強引に進めていかないように、丁寧な対応をしていっていただきたいと思います。"},{"i":255,"speaker":"あくつ委員長","text":"質問でよろしいですか。"},{"i":256,"speaker":"のだて委員","text":"では、いかがでしょうか。"},{"i":257,"speaker":"廣田子ども家庭支援課長","text":"区といたしましては、払わないのか、払えないのかという確認をしたいので、連絡をとりたいという形をとっているのですが、５件の方に関しては、連絡に応じてくれないので、状況を把握できないので、払えない方についてはそれなりの対処ができるのですが、連絡がとれないことには対処ができませんので、訴えを起こして、裁判所から通知が行くと連絡が来る方もいらっしゃるので、それで話し合いができれば和解に持っていくということを考えているところです。"},{"i":258,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":259,"speaker":"高橋（し）委員","text":"済みません。事務事業概要を見ると、１年で何人かしか貸し付けていないと思うのですけれども。それで、これだけいらっしゃるということは、借りた方からなかなか返金されにくいというか、何かそういうところで、お貸しして、返金がかなり滞るという現実があるのかなというところが１つで。これらの方は、何年か前からの話だと思うのですが、そういった点と。\nあと、１２０万円というのは、随分、額があれだと思ったのですけれども。私立で３年間、入学金も借りていても５、６０万円だと思ったのですけれども、その辺、済みません。"},{"i":260,"speaker":"廣田子ども家庭支援課長","text":"奨学金につきましては、３年間、学校に行っている間に貸し出しをしまして、その上、大学等に行っていらっしゃる間は返還を猶予されますので、その後の返還になるという形になっているので、おくれおくれで返還される形になっております。\n滞納に関しては、平成２４年に弁護士を導入するまでは、かなりの件数がございまして、昭和のころからの債権も持っていたというところで、今、大分そのときよりも、債権としては半分ぐらいになっておりますが、古いものもあるような状況です。今回、訴えを提起しているところは５年くらい、５年前後、滞納している方々に訴えを起こしているようなことになります。"},{"i":261,"speaker":"あくつ委員長","text":"１２０万円。"},{"i":262,"speaker":"廣田子ども家庭支援課長","text":"１２０万円については、ちょっと調べさせていただければと。済みません。"},{"i":263,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":264,"speaker":"新妻委員","text":"済みません。督促を、それぞれシルバー人材センター、または弁護士によるというところですけれども、予算もかかっていると思うのですが、これを回収するに当たっての、どれだけお金がかかっているのか、お聞かせください。"},{"i":265,"speaker":"廣田子ども家庭支援課長","text":"シルバー人材センターにつきましては、総価契約をしておりまして、年間で１３５万円ほどなのですが、２名の方に定期的に訪問をしていただいているところです。"},{"i":266,"speaker":"あくつ委員長","text":"弁護士。"},{"i":267,"speaker":"廣田子ども家庭支援課長","text":"弁護士につきましては、１件１件で着手金をまず３万５,０００円プラス消費税という形でお支払いをしまして、成功報酬を、その全納した場合であるとか、分納合意したときであるとかによって、パーセンテージを決めてお支払いするような形になっておりますので、実績払いということになっています。"},{"i":268,"speaker":"あくつ委員長","text":"総額はわかりますでしょうか。"},{"i":269,"speaker":"廣田子ども家庭支援課長","text":"少々お待ちください。\n弁護士につきましては、平成２７年度で、着手金７３万３,０００円。失礼いたしました。総額で２８１万円余です。"},{"i":270,"speaker":"新妻委員","text":"ありがとうございます。これは、基本、区の持ち出しというふうに考えてよろしいのですか。"},{"i":271,"speaker":"廣田子ども家庭支援課長","text":"そうですね。委託料については区の持ち出しになっておりますが、回収した金額は、委託料よりも上回っているので、何もしないよりも回収したお金の中から報酬を払っているというところで、費用対効果はあると考えています。"},{"i":272,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":273,"speaker":"鈴木（博）委員","text":"本当に貧しくて返せない人は非常にかわいそうだと思うし、ある程度、手を尽くさなければいけないと思うのですが。確信的に返さない人も結構いますから、路上駐車とか何か見ても、いろいろな方がいらっしゃるということは、骨身にしみてわかると思うので。例えば、こういう方で、やはりある程度、強制的にでも回収したほうがいい人と、この人はいろいろと救いの手を差し伸べなければいけないのだということを、何かできちんとその辺を精査していただいて、逃げ得は、やはり、非常に好ましくないと思うのですよね。\n今の新妻委員の質問にもあったと思うのですけれども、たとえ赤字でも、やはりとらなければいけないときはしっかりとったほうがいいと思う。それは社会道徳を維持するのに必要なことだと思うから。だからやはり、きちんと分けて、逃げ得とか、ずるい人間が、正直者がばかを見ないような社会にしていくように、その辺はくれぐれもお願いしたいと思うのですね。何かというと、すぐ腰が引けて、やれ人権だ、やれ何とかだとか言って、ずるい、こすっからい人間ばかり得するような社会というのは、非常に好ましくないと思うので。その辺は、やはり調べることは調べて、必要なことはきちんとやっていただくということが、正直にきちんとお金を払って、税金を払って生きていく、やはり給料をもらう者の最低限の役割なのではないかと思うのですが。そういう意見に関してはいかがでしょうか。"},{"i":274,"speaker":"廣田子ども家庭支援課長","text":"委員ご指摘のとおり、返せない人、返さない人というのが両方いらっしゃるかと思うのですが、反応がない方に対しては、弁護士に委任すると、かなり探せる権限も持っておりますので、探しまして、通帳も持ってきて、財産について確認をし、聞き取りもするという形で、払える方には払っていただく方向で、弁護士を入れたことで、大分、取れるようになってきております。\nさらに、返せない方につきましては、生活状況を確認しまして、生保を上回るくらいの収入はのこさなければならないので、それを残したところで、どれぐらい返せるかというところで、分納の合意をしたりとかというところをしていまして、適正な管理ができるようにということで、きちんと聞き取りをやって、取るものは取る、返せない人に対しては、きちんと出てきていただいて、不能欠損で落とすためには、客観的な事実を積み重ねる必要があるので、ぜひ出てきてほしいと考えながら、訴えも辞さないという形をとっております。"},{"i":275,"speaker":"鈴木（博）委員","text":"弁護士というのは、どういう方にお願いしているのでしょうか。"},{"i":276,"speaker":"廣田子ども家庭支援課長","text":"実際に弁護士事務所に委託契約、委任をしているのですが、私債権の管理の条例を策定するときにかかわっていただいた弁護士の方を通じてご紹介いただきまして、江戸川区でかなりの実績、江戸川区、かなり滞納があった分を、かなりの実績を上げた弁護士事務所を選びまして、債権管理を主にやってらっしゃる弁護士事務所に委託しております。"},{"i":277,"speaker":"鈴木（博）委員","text":"例えば、男女共同参画などであると、法テラスの弁護士の方がいろいろとご活躍されていると思うのですけれども。この弁護士で、要するに債権で、たくさん取れたからすご腕だというのではないと思うのですよね。やはりその辺、先ほどの質問のところとも関連するのですけれども、きちんと、たくさん回収するというよりも、いろいろ相手のことを考えて、ある程度、公共的な福祉なども踏まえた上で活動されるような弁護士の方にお願いするのが一番いいのではないかと思うのですけれども。そういう点は、検討とか踏まえて選択されているのでしょうか。\nあと、お金も。例えば法テラスなどですと、安いですよね。弁護士費用をたくさん払うというよりは、むしろ公的な色彩を強く持っているような方にも流用できるのではないかと思います。"},{"i":278,"speaker":"廣田子ども家庭支援課長","text":"回収に当たりましては、丁寧な聞き取りをやっていただいておりまして、借受人自体が若い方もいらっしゃるので、フリーター状態にあった場合には、就職するところまで聞き取りを何回も繰り返して、就業するまではストップして、働くようになったら収入を見て、それに見合った金額をいただくというような形で、丁寧な対応をしていただける弁護士、先方から、面談記録が全部上がってきますので、全部目を通しておりますが、きちんと対応していただいていると認識しております。\n金額につきましては、着手金の金額については、相場では１０万円以上は取られるというところを、自治体ということで３万円台でやっていただいているというところで、そんなに高く払っているという認識はないです。"},{"i":279,"speaker":"鈴木（博）委員","text":"ご配慮されているということですね。"},{"i":280,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":281,"speaker":"あべ委員","text":"質問になります。この資料なのですけれども、被告のお名前がフルネームで入っている資料になっている。委員会では構わないのですけれども、閲覧なども全てこの状態になっているのでしょうか。ちょっと、個人情報の扱い、特に若年の方が被告となると、ちょっと社会的に影響もあるものですから。どのような扱いになっているか教えてください。"},{"i":282,"speaker":"廣田子ども家庭支援課長","text":"この個人名の部分につきましては、傍聴用と公開は、マスキングされております。"},{"i":283,"speaker":"あべ委員","text":"ありがとうございます。一応確認させていただきました。\n先ほどから、かなり丁寧な対応をされているということなのですが、この５件については、連絡がないということではありますが、それぞれ生活状況を把握されて、返済能力ありと判断された上での提訴ということで理解してよろしいでしょうか。"},{"i":284,"speaker":"廣田子ども家庭支援課長","text":"連絡が全くない２件につきましては、生活状況の確認はできておりませんで、とにかく状況を聞きたい、会いたいので、訴えて会おうとしているという状況です。\nそのほかの方につきましては、連絡があって、返還するのが厳しい状況だというとか、途中まで聞いている人もいるのですけれども、それに関して、きちんと聞き取りをしたいので、出てきていただくために提訴しているという意味合いのほうが強いです。"},{"i":285,"speaker":"あべ委員","text":"滞納はこれに限らず、例えば保育料等の滞納とか、各課で持ってらっしゃると思うのですけれども。話を聞くために提訴して、民事とはいえ被告にする。借受人は、まだお若い方々ですよね。ほかの方法というのは、弁護士さんも入ってらっしゃることですし、全く居所不明ということであれば別ですけれども。それ以外の方法というのは、済みません。ほかにはとられる余地はなかったのでしょうか。"},{"i":286,"speaker":"廣田子ども家庭支援課長","text":"あらかじめ、区内の方につきましては、シルバー人材センターの方に訪問にも行っていただいておりますし、電話もさせていただき、文書でも連絡をしているのですけれども、文書も受取拒否をしてしまっているので、私債権なので、払えないという意思表示をしてもらわないと、不能欠損でも落とせませんので、適正な債権管理ということで、いたし方なく提訴し、裁判所から連絡が行っています。裁判所から連絡が行くと、連絡が来る方もいらっしゃるので、そうすると、あらかじめ和解のお話をさせていただくようなこともできますので、いたし方なくということでご理解いただきたいと思います。"},{"i":287,"speaker":"あべ委員","text":"この奨学金に関しては、これまで何回ぐらい、何件の提訴をして、その後、どのような形になっているのか。皆さん、連絡がついて、それぞれ、それなりにお支払いいただいて終わり、ということであればいいのですけれども、その後について把握されていますか。"},{"i":288,"speaker":"廣田子ども家庭支援課長","text":"今回の提訴分を入れない数字なのですが、平成２４年から弁護士に委任しまして、平成２５年から提訴とかをしていますが、全体で提訴したのが３４件になります。その後、和解できたのが１４件です。分納合意ができたのが３件。あとは、提訴はしたのですが、本当に、明らかに払える能力がないということが、お話をしてわかったので、取り下げたのが３件。裁判所にも訪れなかったため、債務名義をとるということで判決をいただいたのが１４件という形になっております。"},{"i":289,"speaker":"あべ委員","text":"ありがとうございます。私債権だと、生活状況も、区としてその他の方法で把握するというのは、難しいのでしょうかね。提訴をしたことで連絡してくださる方がいらっしゃるというのは、１つ提訴のメリットといいますか、それによって可能になることだとは思うのですが、提訴によって逆に追い詰められてしまう家庭があったりすると、ちょっと、非常に影響の大きい方法だなというふうに思います。今回の５件の中でも、全く返済していないご家庭もあれば、９割方返済したところでとまっている。９割返済してというのは、そんなに、悪質で逃げているというよりは、何らかの事情があるのではないかなと、お名前が変わっていることなどを見ても、何と言ったらいいのですかね。その辺が、提訴したら連絡があるだろうからというだけでは、ちょっといろいろな家庭の事情も透けてみえるような中で、それもご担当として苦渋の選択だと思うのですけれども、やはり、提訴に全てがなじむわけではないのではないかなと。その辺は、区としてどのようにお考えですか。"},{"i":290,"speaker":"廣田子ども家庭支援課長","text":"区といたしましても、提訴がよしとしているわけではございませんが、度重なる督促をさせていただいて、弁護士に委任する前は、ここで、連絡をいただけないと、弁護士に委任しますと。弁護士から督促が行くときも、これで反応しないと提訴をしますという予告はさせていただいているところです。税のような強制債権と違いますので、強制的に調べたりとかいう方法、財産を押さえたりすることができませんので、そうすると、苦しいながらも返していらっしゃる方もたくさんいらっしゃるので、公平性を考えると、苦渋の選択と考えていただければと思います。"},{"i":291,"speaker":"あべ委員","text":"済みません。ちょっと確認なのですけれども。これは、奨学金の貸与に関しては、おくれると遅延金というのが発生するのでしたっけ。もし発生するとしたら、貸付額の中にそれも入っているのか、入っていないのか。それも合わせてご答弁してください。"},{"i":292,"speaker":"廣田子ども家庭支援課長","text":"この貸付金の滞納額の中には、これは貸し付けた金額だけしか入ってございません。延滞金が生じるのですが、年で０.５％〔翌日「５％」と答弁訂正あり〕という形ですが、分納の合意等をして、期日までにお支払いいただく、延滞金については請求することができるという規定になっておりますので、話し合いに応じて、約束どおり分納していただいた場合には、延滞金をもらわないというふうな決定をすることというか、今まではそういう決定をしていて、延滞金を今までは、取ったことは、実績はないです。"},{"i":293,"speaker":"あべ委員","text":"わかりました。ありがとうございます。\n最後になりますが、確かに、基本的に、借りたものは返すという形で運用されている、それが仕組みのベースだと思います。ただ、この５件の中を見ていても、そもそも返す意思がないわけではなさそうだと思われるようなケースもあり、ぜひ、生活実態と合わせて、提訴によらない方法というのも、今後もぜひ模索していただきたいと思います。とりあえず以上です。"},{"i":294,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":295,"speaker":"飯沼委員","text":"まず、文書、訪問、弁護士による督促で、順番に進むのかなと思っていたのですが、そうではないということで。それぞれのところで、例えば、文書を出したことで支払いに応じてくれて、件数が減って。ここには２２５件と書いてあります。このところで、どのくらい効果があったのかと。支払いに通じたのか。訪問督促のところも、月１５０戸とありますけれども、対象がどのくらいに、初めの２２５件から減っているのかというところも、それぞれの督促のところの効果というのを教えていただきたいのと。\nあと、文書督促のところ、どのような文書を出しているのか、ちょっと、封筒の外と、中身もどういうことが書いてあるのか、教えていただきたいと思います。"},{"i":296,"speaker":"廣田子ども家庭支援課長","text":"督促の効果、文書だけではないと思うのですけれども、２２５件あったものが、大体１５０件弱ぐらいに、電話連絡したりとかもありますけれども、減っています。訪問督促については、訪問はたくさんするのですけれども、大体、月に回収できるのが２０件ぐらい。２人の方が訪問されているのですけれども、２０件ぐらいで、年間ですと、回収できるのが、延べの件数ですが、２００件前後という形で、１５０万円から１７０万円ぐらい、毎年回収していただいて、振り込んだりするのがなかなかできないという方は、集金に来てもらっているような形で、コミュニケーションをとってもらっています。何かちょっと込み入ったケースですと職員が同行していくという形で、丁寧に拾っております。\n失礼しました。督促の文書の内容ですけれども、そんなに特別なことではなくて、いついつの幾らの債権について、速やかにお返しくださいという形で、封筒そのものは、名前が出ているだけで、督促状であることがあけてみなければわからないですが、シンプルな内容です。"},{"i":297,"speaker":"飯沼委員","text":"こういったケース、本当にさまざまなケースがあると思うのですが、できるだけ早くお話ができる、生活の困難な方に対しての手立てなどもいろいろあるので、早くお話をして、解決の道が開かれればいいなと思っているのですけれども。結構、滞納してしまっているという人は、なかなかそこに踏み切れなくて、言葉は悪いけれども、逃げて、避けているという方もいらっしゃると思うので。なるべく早く、実際に、さっき、込み入ったケースは職員がということですけれども、シルバーさんに任せるだけではなくて、職員の方が会っていろいろ相談に乗れるというような状況になるといいと思っているのですけれども。\n生活困難な人への対応で、福祉の必要な方など、支援のケースにつながったのがどのくらいあるのか、ちょっと教えていただけたらと思います。"},{"i":298,"speaker":"廣田子ども家庭支援課長","text":"福祉につながるというよりも、確認したら生保の受給者だったというところで、ご本人から、相談いただければ徴収停止をかけてあげられるので。生保だったという方はいらっしゃいますが、どちらかというと、弁護士と話して、就労もきちんとしてくれたというようなケースは見られております。弁護士への委任の件数が年々減ってきて、前はたくさんあったのですけれども、だんだん、もう整理ができてきたので、平成２８年度はもしかしたら委任しなくても済むかもしれないくらいまでは来ているので、なるべく電話等で、１件１件丁寧にやれるような時期に差しかかってきたかなという状況です。"},{"i":299,"speaker":"飯沼委員","text":"ごめんなさい。先に聞こうと思った。一番最初の２２５件、平成２７年７月３０日現在の、これは何年間分の件数なのか。どこからの起点で数えてあるのかを教えてください。"},{"i":300,"speaker":"廣田子ども家庭支援課長","text":"済みません。いつから、何年からかは申し上げられないのですけれども、昭和の時代から残っています。"},{"i":301,"speaker":"飯沼委員","text":"１件１件いろいろな方がいらっしゃるし、丁寧にはやってくださっていると思うのですが、とにかく、長くかかるとこじれてしまうし、わからないこともいっぱい出てくるし、できるだけ早期に問題点が明らかになり、コンタクトがとれる、コミュニケーションがとれるような状況に、なるべく努力をしていただきたいなと思うのと。\nさっきは、余り福祉につながるというケースはなくて、わかったら生保の受給者だとかということですけれども。今、本当に、お勉強、学校に行きたくてもなかなか行かれない、家庭の困難な状況の中でも、やはりこの奨学金制度というのは、本当にかけがえのない制度で、多くの方に使っていただきたいという制度でもありますので。これが、将来に負担になっていかないように、私もできたら提訴といった形ではなく、早期にどんどん働きかけをして、状況をつかんで解決をしていく方向に行っていただきたいと思いますので、よろしくお願いいたします。"},{"i":302,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。\nご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(2) 大崎図書館の移転について"},{"i":303,"speaker":"あくつ委員長","text":"次に、(2)大崎図書館の移転についてを議題に供します。\n本件につきまして理事者より説明願います。"},{"i":304,"speaker":"木村品川図書館長","text":"私からは、大崎図書館の移転について、ご説明をいたします。\n本件に関しましては、今まで、本会議、常任委員会、その他特別委員会で報告、ご説明をしてまいりましたけれども、このたび、移転先のほうの工事業者が決まったというところもございまして、現時点での状況をご報告という形で説明をさせていただきます。\nまずは、大崎図書館移転に関してです。新しい移転先でございますけれども、北品川５丁目２番、区立御殿山小学校の西側の敷地、すぐ隣でございます。概要といたしましては、介護老人保健施設・通所リハビリテーション・訪問看護ステーション・訪問リハビリ等との複合施設、区立図書館が合わさっているという形になります。\n建物は鉄骨造の地上８階、地下１階、図書館は２階になります。それから地下１階が駐輪場という形になります。面積は１,５７５余平方メートルという形です。今後、中身については、多少変わる予定がございます。現時点での予定ということでございます。\n建設の主体でございますが、今週の土曜日でございますけれども、平成２８年１０月１日から５０年間の定期借地権設定契約により、区から計画地を借り受けた事業者、公益財団法人河野臨牀医学研究所、ここが建設主体という形になります。から、土地を借り受けて、建てるというような形です。ここで図書館を含めた複合施設を、一体的に整備をするという形です。区立図書館につきましては、区所有施設といたします。\n建設事業者につきましては、入札の結果、株式会社安藤・間、こちらに決まりました。\nレイアウト、現時点でのイメージでございます。簡単にご説明いたしますが、この四角の右下の部分、青い四角があると思います。こちらがエレベーター、それを囲むように階段という形になっています。これで２階に上がってきていまして、真ん中に受付のカウンター、それから右上に児童コーナー、左下に、この書架というのは本棚のことでございます。閲覧席が、これは下側なのですけれども、ガラス窓に沿った形で、ずっと１列に並ぶような形、それから、若干のまた閲覧席を用意しております。左上に関しましては、主にスタッフのバックヤード、それから閉架書庫というような形になっております。\n裏面を見ていただきまして、本日、夜ですけれども、近隣の方々への工事の説明会を予定しております。御殿山小学校で行います。それから、１０月１日からでございますが工事の着工、それから平成３０年３月末に竣工、５月以降に開設予定という形で進んでおります。\n２番目でございますけれども、この移転に伴いまして、現地のほうからの請願の採択によりまして、代替施設というところで、芳水小学校の中に図書機能を持った施設を建設するという中身でございます。住所につきましては、芳水小学校の中です。現在も芳水小学校は仮設校舎で、実際に授業をしておりまして、建設工事も進んでいるところでございます。こちらの中に図書スペース、多目的室を設ける。敷地面積は６００平方メートルで、図書関連のところが５００平方メートル、それから多目的室が１００平方メートル、これも今後の設計で多少前後する場合もありますので、予定という形にしております。\n躯体に関しましては、芳水小学校の改築工事で対応しておりまして、備品、内装の整備というところでございます。\nレイアウトのイメージでございますけれども、こちらの真ん中のロビーというところ、大崎駅からそのままのレベルで入ってこられるような形になっておりますけれども、主に左側が図書の機能の施設、それから右側に多目的室という形で、合計６００平方メートルという形で考えております。\nこちらのほうにつきましては、平成２９年度設計で、平成３０年度内装工事、備品設置で、平成３１年１月、これは学校の改築と同じスケジュールでございますけれども、開設の予定を目指しております。\nそれから、この代替施設のもう１つといたしまして、大崎駅西口の図書取次スペースというところにつきまして、こちらは大崎駅西口の再開発ビルの会議室にスペース設置を現在検討中ということでございます。\n私からの報告は以上でございます。"},{"i":305,"speaker":"あくつ委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言願います。"},{"i":306,"speaker":"のだて委員","text":"まず、１番と２番共通のところですけれども、設計をやっていくということなので、わかれば、蔵書数、何冊ぐらい図書があるのか伺いたいと思います。\nそして、運営はどういったところを検討しているのか、どこがやっていくのかということと、人員配置ですね。何人の方がこの業務に、どんな業務を委託していくのかということもあると思いますが、何人の方がいらっしゃるのか伺いたいと思います。\nそして、芳水小学校内の２番のところですけれども、図書機能施設と書いてあるのですが、これはどういう位置づけになるのでしょうか。図書館とは違うということなのか伺いたいと思います。"},{"i":307,"speaker":"木村品川図書館長","text":"移転先の蔵書数でございますけれども、現在、約７万３,０００冊程度を予定しております。\nそれから、運営につきましては、現在、大崎図書館は指定管理者が運営しておりますけれども、引き続き指定管理者の運営という形で想定をしております。\n人員につきましては、こちらの運営のほう、これからまだ検討しているところでございまして、実際に１つ、新しいサービスを展開しようというところもございます。新しいシステムというのですか、そういう部分も中では研究、検討しているところでございまして、まだ現時点では何人ということは申し上げられないところでございます。\nそれから、芳水小学校に関しましては、こちらの図書機能施設というのは、図書館と言わないというところは、いわゆる図書館としての機能、フルセットというようなイメージではない形で、本は置いて、実際に閲覧もできる、それからいろいろなお話し会その他の事業も展開できるというような形で、今のところは考えておりますけれども、こちらの取り扱い、それから位置づけに関しましても、これからまだ検討しているところでございます。"},{"i":308,"speaker":"のだて委員","text":"７万３,０００冊ということですが、この１番と２番で何冊なのかということもお知らせいただければと思います。\nそして、新しいサービスの提供をしていくということですが、まだ検討中ということなのでしょうか。どういったことがあるのか、もし話せることがあれば教えていただければと思います。\nそして、先ほどちょっとご説明あったかもしれませんが、２番の芳水小学校のところで、これまで大崎図書館では読み聞かせ等よくやっているという話を聞いているのですが、そのためのスペースがあったというところで、今回、この芳水小学校のところに図書機能施設、できたときに、読み聞かせスペース、なくなっているように見えるのですが、今後どうしていくのか伺いたいと思います。\nあと、大崎駅の西口の取次スペースなのですが、これは西口再開発ビル会議室ということですが、どこになるのでしょうか。そして何ができるのか、現在の、検討中ということですけれども、現在の状況を教えてください。\n最後に、図書ですね。新たに２カ所の図書の施設ができるというところで、今までは大崎図書館にあった図書は移転、移していかれることになるのか、新たに買うことになるのか。当初冊数の問題は、増えてくる、２カ所になるので増えると思うのですが、その点のお聞きしたいと思います。"},{"i":309,"speaker":"木村品川図書館長","text":"まず、移転先のほうの新しいサービスでございますけれども、今、検討中なのは、いわゆるコンシェルジュ、千代田区の図書館でも、もう既に導入されているのですけれども、ご案内の人がフロアにいつもいて、例えば、子育てに関することであるとか、健康に関すること、本に関すること、そういうものをご案内するというようなところ。それから、今、一部のほかの区立の図書館で導入されていますけれども、セルフサービスの自動貸出・自動返却機というのがあるのですけれども、図書館に来られる方が、ほとんどが実際に本をただ返す、ただ借りるというような形のところも利用が多いものですから、その辺を自動化するというような部分の考えもございまして。そこはちょっと、先ほどのスタッフの数ともかかわるところでございます。\nそれから、芳水小学校の読み聞かせに関しましては、今、多目的室、この右側の部屋、こちらを想定をしているところでございます。\nそれから、西口の取次サービス、どこにということでございますけれども、こちらのほうは、現在、調整、検討、先方とやっているところでございます。ちょっとこの場では差し控えさせていただきたいところでございます。\n基本的には、サービスコーナー、大井町、武蔵小山で展開しています図書のほうの取り次ぎのサービス、プラスアルファ、そこで親子で本が楽しめる、あるいは交流ができるというような若干のスペースを想定した形で、今のところ考えているところでございます。\nそれから、本を買うかどうかというところでございますけれども、基本的には、芳水小学校のほうには、約５万冊の蔵書を、予定を今しているところでございまして、実際的に増やしますので、その分については新たに用意をするというような形になろうかというふうに思います。"},{"i":310,"speaker":"のだて委員","text":"会派としては、これまでも、大崎図書館はやはり老朽化ということも、区のほうから説明ありますけれども、やはり現地でこれまで歴史もあってやってきた中で、利用率も高いというところで、現地での存続を求めてまいりました。移転しなくても、改修や建てかえを行っていけばいいと思うのですが、改めて大崎図書館の現地での存続を求めたいと思いますが、いかがでしょうか。"},{"i":311,"speaker":"木村品川図書館長","text":"今まで議会でもご説明を繰り返しておりますとおり、移転に関しましての考え方は変えるつもりはございません。その代替として、今ご説明しました芳水小学校のところの整備、こちらをしっかりやっていくというところで、地元の方、今まで愛してくださった方のご期待に応えたいというふうに思っております。"},{"i":312,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":313,"speaker":"あべ委員","text":"まず、新しいほうの大崎図書館、移転先のほうについてお伺いしたいのですが。かなり広く児童コーナーをとってあるように見えますが、これは具体的にどのような内容になっていくのか。児童本とその閲覧。それ以外にも、例えばもとの大崎図書館にあったようなおはなしの部屋みたいな。何か、今、決まっている段階のものがあれば、イメージでも教えていただければと思います。"},{"i":314,"speaker":"木村品川図書館長","text":"現在、今ありました、おはなしの、いわゆる地べたに座って本を読み聞かせするような、そういうスペースも想定しています。それから、子育ての交流スペースというのですか、この中で、なかなか厳しい部分もありますけれども、いわゆる近隣の方々の、子育て世代の方々が交流するようなスペースのようなものも、基本的におはなし会と共用するかもしれませんけれども、そういうようなところも考えているところです。\nそれから、いわゆるベビーカーの置き場でありますとか、あとは基本的に本を置く、本が読めるスペースというようなところで考えております。"},{"i":315,"speaker":"あべ委員","text":"あと、閲覧席、これは何席ぐらい考えていらっしゃいますでしょうか。\nあと、先ほどのご答弁で、交流のほうもということで、それはそれで非常にいいことだと思うのですが、このエリアは非常に人口が増えていて、さまざまなニーズがあります。だから、ぜひ子育て世代にも配慮していただきたいし、そうではなくて高齢者の方々、特に図書館はリタイアした方々のニーズが非常に大きいので、うまく、声などでお互いが不快にならないような工夫も、ぜひしていただきたいと思うのですが、その点も合わせて答弁をお願いします。"},{"i":316,"speaker":"木村品川図書館長","text":"閲覧席につきましては、全部で１３０席程度を予定しております。うち、児童につきましては４５席です。\n今、いただきました交流につきましては、私どもも意識しておりまして、いわゆるお子さん、子育ての方々、それからおっしゃられました高齢者の方、今回は病院と老健の複合施設ということもございまして、そういう部分では、そういう方々のご来場も多いだろうというところで、もう具体的に、そこは計画の説明会とかで、いわゆる、うるさいようなのはちょっと勘弁してくれというような部分も、いろいろな声をいただいておりますので、その辺、配慮をしてまいりたいと思うのと、あとはやはり、ビジネス街というところがございます。通信センター等もそばにございますので、そういう意味でも、そういう方々も含めた形で。オールラウンドと言ってしまうと言葉は普通になってしまいますけれども、いろいろな方々が落ち着いて本に親しめるような、そういう場を作っていただきたいと思っています。"},{"i":317,"speaker":"あべ委員","text":"ありがとうございます。これについては、また、２年後の開館まで、いろいろと要望を出させていただきたいと思いますが、基本的にこのエリア、人口に比べて公共施設が余り多くないというのもありますので、地域の皆さん、大変、楽しみにされている施設でもあります。ぜひ、今後整備を進めていただければと思います。\nあと、この建設躯体等のところであります、定期借地権設定契約、これはいよいよ１０月１日からということです。これまで、まだいろいろ途中だからということで、契約の金額なども明らかになっていなかった気がするのですけれども、そもそもこれで、定借でどのくらいの、どういった内容の契約になっているのか、内容を教えていただければと思いますが、わかりますでしょうか。"},{"i":318,"speaker":"木村品川図書館長","text":"定期借地権のことでよろしいでしょうか。"},{"i":319,"speaker":"あべ委員","text":"はい。"},{"i":320,"speaker":"木村品川図書館長","text":"貸付料が、年額で２,０６０万３,３６４円です。年額です。月額で１７１万６,９４７円、こちらを予定をしているというふうに聞いております。"},{"i":321,"speaker":"あべ委員","text":"わかりました。逆に図書館のほうは、建物の一部のフロアをお借りする形になるのでしょうかね。それとも、これは、区の持ち分として所有を残す形なのかも教えてください。"},{"i":322,"speaker":"木村品川図書館長","text":"区分所有として、区のものとして所有します。"},{"i":323,"speaker":"あべ委員","text":"はい。ありがとうございました。\nそれから、芳水小学校のほうの図書機能ということなのですが、これは、済みません。私、聞き逃したのかもしれないのですけれども、この図書機能施設というものには、例えば司書さんとか、あとリファレンス機能とか、そういったものも備えることになるのですか。"},{"i":324,"speaker":"木村品川図書館長","text":"基本的には、今おっしゃられたリファレンス、それから司書という形を備えた形で考えております。"},{"i":325,"speaker":"あべ委員","text":"ありがとうございます。あと、取次スペースなのですが、これは検討中ということですが、建物自体も検討中ですか。この西口再開発ビルというのは、いわゆる新区画を指していらっしゃるのでしょうか。それとも、その他のビルも含めて、どこか検討中ということなのかというのが１つと。\n先ほどのご答弁の中で、取り次ぎプラス親子コーナーと、私、ちょっとこういうイメージではなくて、本当に普通の取次サービス、あるいは武蔵小山などのイメージだったものですから、ちょっと伺ってびっくりしたのですけれども。とすると、ちょっと広さがあって、子どもたちも出入りしてということになると、逆に、まだ未定かもしれませんけれども、営業時間といったらいいのか、開設時間はどのような感じになるのでしょうか。むしろ、取次サービスが駅にあるとなると、機能はシンプルでも朝早くから夜遅くまであいているほうが、駅としてはしっくりくるかなと思ったのですけれども。そこに親子となると、ちょっとイメージが散漫になってしまって。もう少し詳しく教えてください。"},{"i":326,"speaker":"木村品川図書館長","text":"場所でございますが、今、１５０平方メートル程度のところ、これも先ほどの繰り返しになりますけれども、今、どこのビルということまで、ちょっと申し上げられないものですから。そちらで検討しているところでございます。\n開設時間につきましては、おっしゃられる、少し、現状の幅よりも、いわゆる通勤通学を含めた形で、少し拡大できればいいかなというところで、今、考えているところではございます。いわゆる、そのぐらいの広さはございますので、大井町のサービスコーナー、プラスアルファのイメージをしていただいて、そういう形の集えるスペースというのですか、そういうものをちょっと予定をしているものでございますが、これも検討中でございます。"},{"i":327,"speaker":"あべ委員","text":"１５０平方メートルというと、大崎駅周辺としてはかなり広い公共施設になるなと感じております。せっかくそれだけの広さがあるのであれば、取次サービスにちょっと交流ができるという、何かフリースペースみたいなイメージより、もう少し踏み込んで機能を持たないと、逆にもったいない気もするのですよね。いろいろ、１５０平方メートルというと、できることがとても増えてくると思うのですが、これは今後、どのような形で検討をされていくのでしょうか。単なるフリースペースで終わるということはないのですよね。"},{"i":328,"speaker":"木村品川図書館長","text":"今、委員からのご指摘もございましたということもないのですけれども、実際にそれも踏まえまして、まだ、いわゆる検討段階でございますので、そこの活用方法、使い方という形は、さらにちょっと練っていきたいというふうに考えております。"},{"i":329,"speaker":"あべ委員","text":"このエリアは、本当に、フリーで使える場というのが少なくて。ですので、ぜひ、こういう場を設けられるのであれば、この先、オープンまでもう少し時間が。あれ、時期が書いていない。いつごろオープンの予定なのかということと、それから、どういうふうに使うかということを、ぜひ、いろいろな形で地元の意見、あるいは議会の意見なども聞きながら進めていっていただきたいと思いますが、いかがでしょうか。質問です。"},{"i":330,"speaker":"木村品川図書館長","text":"オープンの時期につきましては、ちょっと未定という形で。ちょっと先方の調整との関係もございまして、今、そういう形でございます。それから、使用方法、活用方法につきましては、引き続き、おっしゃるとおり、いろいろな方の意見を聞きながら検討してまいりたいと思っております。"},{"i":331,"speaker":"あべ委員","text":"ということで、このたび新たにご提案が、小学校西側敷地に、区内としてはかなりの規模の図書館が新設され、一方で芳水小学校の中にも司書さんを備えた図書機能施設、そして大崎駅西口、これも取次スペースというよりは、かなり広くていろいろな可能性を持った、しかも図書にかかわる施設が３つできようとしているわけで、これはこれで大変ありがたいことだと思います。\n区内全体を見回したときに、品川、大崎エリアくらいの図書機能というのは、かなり充実してきたと思うのですけれども、それだけに、区内のその他のエリア、特に荏原地区における図書機能が、その面積、蔵書、建物の老朽具合いなども含めて、さらに差が開いてしまったかなというふうにも感じております。その点は、すぐにすぐというわけにはいかないと思うのですけれども、その地域の、埋めていくような中長期的なお考えというのは、区としては問題意識として持っているかどうか、確認したいと思います。"},{"i":332,"speaker":"木村品川図書館長","text":"ご指摘の状態は確かにございまして。老朽化をしている施設は、やはり荏原に、集中とまではいかないですけれども、かなりございます。そういう形で、これから、改築、あるいは複合施設化、そういう建てかえの計画の中で、ある程度、実際に、今、この大崎で展開しているような新たな展開であるとか、例えば面積の拡充だとか、そういう形で可能であれば、そういう形で考えていきたいというふうに思っておりますが。新規で図書館を何かというような形の考えは、今のところございません。"},{"i":333,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":334,"speaker":"飯沼委員","text":"まず、この今日の、移転についてという下の２行なのですが、大崎地区のさらなる文化教育機能の充実を図るため、施設の老朽化等に伴う大崎図書館を移転するとともに、芳水小学校内に図書機能施設を整備するということで、北品川の地域、人口がどんどん増えているといった意味では、ここに新しい図書館ができるということはとても重要なことですし、意義があると思うのですが、現大崎図書館のことを考えると、この大崎地域の方々のことを考えたら、とても文化教育機能の充実なんて言えない。言ってみたら、建物は新しいところに入るかもしれないけれども、規模も小さくなるし、内容がちょっとよくわからない。図書館という位置づけにもなっていないということにおいては、この大崎の現図書館がある地域のところの文化的な面を考えたときに、私はこれでは納得できない。何か、地域の方が同じような規模というか、現地に建てかえてほしい。この思いからしたら、すごくかけ離れているのではないかなと思うのですが、まず、その点。面積的にも現在の半分ぐらいですよね。蔵書がさっき、５万冊。だから、半分以下ですよね。そんな、規模も小さくなっていく中で、どうなっていくのだろうということでは、これをお伝えしたら、とても失望されてしまうなと思うのですが、その辺はいかがでしょうか。"},{"i":335,"speaker":"木村品川図書館長","text":"こちらにつきましては、今までもそのようなご意見をいただいて、実際にも利用者の方の声からもいただいているようなところでございます。こちらに関しましては、今、いわゆる山手線外側、現大崎図書館側の部分で、なかなか、まとまった敷地の確保が難しいというところもございますし、現在予定しています、平方メートルとしては縮小という形ではございますけれども、近隣で言いますと二葉図書館でありますとか、大森のそばの南大井図書館、荏原町の源氏前図書館、そことほぼ同程度の規模の、いわゆる小規模の図書館、大崎は大規模でございますけれども、そういう意味では違うではないかと言われるかもしれませんが、小規模の図書館としてのスペースは確保してきたつもりでございます。そちらのほうの整備、それから、確かに、館の中でのいわゆる蔵書数としてみればそうかもしれませんけれども、今は、区内で１００万冊というような形の蔵書を持っています。そういう意味では、ご希望される本につきましては、ご予約をいただければ、例えば、どの館にありましても、そういう形でお手にとっていただくことはできますので、そういう部分も活用いただきながら、この新しい芳水小学校の施設についても愛されていくような形で運営をしてまいりたいというふうに考えております。"},{"i":336,"speaker":"飯沼委員","text":"蔵書なのですが、先ほど５万冊ということなのですが、児童図書とか、あと、現在、ここの特色のビジネス図書がどこに行くのか教えていただきたいです。とりあえず、それで。"},{"i":337,"speaker":"木村品川図書館長","text":"児童書の数につきましては、ちょっとまだ、内訳につきましては、詳細を出してきておりませんので、基本的には一般の図書、それから児童の図書、整備してまいる考えでおります。その辺はまだちょっと出しておりません。\nそれから、ビジネス本につきましては、基本的には、新しい大崎のほうに持っていくつもりではございますけれども、これも、今の区の関連という部分で、いわゆる差配ができる部分でございますので、これから検討してまいりたいというふうに思っています。"},{"i":338,"speaker":"飯沼委員","text":"東口のほうも人口が増えていますけれども、今また、開発が西口、どんどん広がっているという意味では、今後、人口もさらに増える。芳水小学校の改築というのもかかわってきていますけれども。そういった意味では、やはりこのご提案では、明らかに縮小だと思うのですね。やはり地域の要求に応えていく図書館、図書機能施設などという曖昧な位置づけではなく、きちんとした、今までと本当に変わらないような機能を持っていくのだということでしたら、図書館はここに残す、向こうに行きました、移転しましたではなくて、北品川のほうは、本当に新たな地域の要求に応えていくという意味では、大崎図書館をしっかり残して、機能もきちんと、図書館としての機能をきちんと持たせるということが大事であると思うので。そこをいつまでも、こうやって曖昧な、図書機能施設などという言葉。あと、まだ全然わからない西口のところに、新たなスペース、そこの両方を合わせて機能を持っていきますというのでは、とても説明にならないと思うのですよね。そういった面で、ぜひ、図書館という機能にしていただきたいということと、同等の、今の機能を確保するというところを、ぜひお答えいただきたいのですが、いかがでしょうか。"},{"i":339,"speaker":"木村品川図書館長","text":"今の点につきまして、内部のほうでも議論になった部分でございます。図書館、いわゆる図書機能施設としてやっていくと、必ずニーズとしては、もっといわゆる図書館としての部分も必要ではないかというところで、必ず出てくるであろうと。そういう部分で、図書館として整備する必要もあるのではないかという声も、確かにございました。現時点の考えにつきましては、基本的に図書館の数をこれ以上、増やさないというところではおります。考えではおりますけれども、今のご指摘も踏まえまして、実際の、その施設としてどういう形が望ましいか、要望されているかという部分も含めまして、重ねてこれからも検討してまいりたいというところで。本日としては、ちょっと、すぐ即答という形でのお答えはできませんけれども、芳水小学校、それから西口に関しましては、今後明らかにご報告をしてまいりたいというふうに考えています。"},{"i":340,"speaker":"飯沼委員","text":"とにかく、品川区は人口も増えていますし、企業も呼び寄せているという立場においては、地域の文化の本当に宝庫と言える図書館です。ここの地に図書館を残したという感じで、ぜひ機能をしっかりと備えてほしいのと、ビジネス関係のところも、あっちに移したというのではなくて、やはり活用される方向を続けていっていただきたいなと思います。ぜひ、地域の方の願いは、この間、何回も請願でも出ております。区のほうにも伝わっていることと思いますので、ぜひぜひ前向きにご検討をよろしくお願いいたします。"},{"i":341,"speaker":"あくつ委員長","text":"ございますでしょうか。\nご発言がないようですので、以上で報告事項を終了いたします。\n────────────────────────────────────────────\n４ その他"},{"i":342,"speaker":"あくつ委員長","text":"次に、予定表４、その他を行います。\nまず、今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、文教委員会にかかわる項目について、所管質問をなさりたい委員がいらっしゃいましたら、その基礎となる一般質問の項目と、それに関する質問内容をこの場でお願いいたします。\nなお、本会議での質問の繰り返しにならないようにお願いをいたします。\nまた、明日、この委員会で理事者からご答弁をいただき、申し出た委員以外の方にも議論に加わっていただくという形で進めていきたいと思います。\nそれでは、所管質問がございましたら、ご発言願います。"},{"i":343,"speaker":"のだて委員","text":"飯沼委員の保育の質問で、ひろまち保育園にかかわって、保育方針の違いということで、質問したのですが、そのときにはご答弁がなく、今回、今日、審議ありましたけれども、幾つもあるというところで、今回明らかになったものもありますが、ほかにもあると思いますので、その項目を具体的に出していただきたい、お答えいただきたいと思います。"},{"i":344,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":345,"speaker":"のだて委員","text":"あと、区の責任がないのかという質問にも、具体的な答弁がありませんでしたので、それについてもお聞きしたいと。その理由ですね。"},{"i":346,"speaker":"あくつ委員長","text":"他にいかがですか。"},{"i":347,"speaker":"飯沼委員","text":"自民党・子ども未来の鈴木真澄議員の保育園の民営化と大規模改修についての質問の項目の中で、ご答弁の中で、保育の質、コスト等、民間委託についての検証を行っていきますというご答弁があったので、この辺の中身をもうちょっと具体的にお伺いしたいなと思っております。よろしくお願いします。"},{"i":348,"speaker":"あくつ委員長","text":"それでは、のだて委員から、一般質問の飯沼委員の保育園の民営化に関するという項目、質問に関連して、先ほどの、保育方針の違いということと、あともう１つは区の責任についてをお聞きしたいということです。\nそれと、飯沼委員のほうからは、鈴木真澄議員の、これも保育の質問に関連して、コストの検証についてというところについてお聞きしたいということでございます。\n念のために確認しますが、一般質問の繰り返しにはならないようにというところですが、ここは確認させていただきたいと思います。\n明日の委員会で理事者のご答弁をいただきたいと思います。\nその他で何かございますでしょうか。\n〔「なし」と呼ぶ者あり〕\nないようですので、その他を終了いたします。\n以上で本日の予定は全て終了いたしました。\n明日も午前１０時からの開会でございます。\nなお、明日の委員会で、行政視察の勉強会を行う予定でおりますので、よろしくお願いいたします。\nこれをもちまして、文教委員会を閉会いたします。\n○午後 ２時３９分閉会"}]});
